/Device/Plc Logic/Application/Modbus_Sla:
PROGRAM Modbus_Slave
VAR
	modTcpSlaveInit:gcan.FB_ModbusTCP_Slave_Init;	//gcan.FB_ModbusTCP_Slave_Init为Modbus TCP Slave初始化功能块
	modTcpSlaveCtrl:gcan.FB_ModbusTCP_Slave_Ctrl;	//gcan.FB_ModbusTCP_Slave_Init为Modbus TCP Slave执行功能块
	eout: BOOL;										//用于承接功能块中完成标志引脚数据的变量
	iSocket: INT;									//用于存放自身socket
	uiErr: UINT;									//用于承接功能块中报错引脚错误信息的变量
	isInit: BOOL:=FALSE;							//用于初始化执行一次的逻辑变量
	arClient:ARRAY[0..10] OF INT;					//用于存放Client即主站的socket

	arDo_data:ARRAY[0..654] OF BOOL;					//用于存放线圈的数据
	arDi_data:ARRAY[0..79] OF BOOL;					//用于存放离散型数据
	//arReg_data:ARRAY[0..10] OF INT;					//用于存放保持型寄存器的数据
	//arAi_data:ARRAY[0..10] OF INT;					//用于存放输入型寄存器的数据
	modbusData	    AT %MW0		: ARRAY[0..654] OF WORD;//用于存放保持型寄存器的数据，接收的数据
	modbusInputRegs	AT %MW660	: ARRAY[0..79] OF WORD;//用于存放输入型寄存器的数据，上报的数据

	enCtr:BOOL:=FALSE;								//Modbus TCP Slave执行功能块使能变量

	Remote_time 	 	:LWORD;
	dif:ULINT;//时延
	iCount				:WORD;
	TypeList1 			:DWORD;
	UTC_Union: float2bit;
	CtrlBool: WORD_AS_BIT;
	bCommReset:BOOL;		//错误复位标识符
	iWatchDogTime:INT;

	Pos1_Union:float2bit;//远控处理数据结构体
	Pos2_Union:float2bit;
	Pos3_Union:float2bit;
	//轴1远控指令，俯仰
	iMode_1 			:INT;  			//轴1模式远控
	rPosCmd_1 		 	:REAL; 			//轴1位置指令远控
	rVelcmd_1 			:REAL; 			//轴1速度指令远控
	rP_1 				:REAL;    	//轴1P远控
	rI_1 			 	:REAL;      	//轴1I远控
	rD_1				:REAL;     	//轴1D远控
	rThreshold_1 	 	:INT:=1;		//轴1积分阈值远控
	rAcceleration_1  	:REAL;			//最大加速度
	rDeceleration_1  	:REAL;			//最大减速度	
	rVelLim_1	  	 	:REAL;			//最大速度

	//轴2远控指令，方位
    iMode_2  		 	:INT; 			//轴2模式远控
	rPosCmd_2 			:REAL; 			//轴2位置指令远控
	rVelcmd_2 			:REAL; 			//轴2速度指令远控
	rP_2 				:REAL;  		//轴2P远控
	rI_2 			 	:REAL;  		//轴2I远控
	rD_2 			 	:REAL;  		//轴2D远控
	rThreshold_2 		:INT;			//轴2积分阈值远控
	rAcceleration_2 	:REAL;			//最大加速度
	rDeceleration_2  	:REAL;			//最大减速度	
	rVelLim_2	  		:REAL;			//最大速度
	//轴3远控指令，方位
    iMode_3  		 	:INT; 			//轴2模式远控
	rPosCmd_3 			:REAL; 			//轴2位置指令远控
	rVelcmd_3 			:REAL; 			//轴2速度指令远控
	rP_3 				:REAL;  		//轴2P远控
	rI_3 			 	:REAL;  		//轴2I远控
	rD_3 			 	:REAL;  		//轴2D远控
	rThreshold_3 		:INT;			//轴2积分阈值远控
	rAcceleration_3 	:REAL;			//最大加速度
	rDeceleration_3  	:REAL;			//最大减速度	
	rVelLim_3	  		:REAL;			//最大速度

	//轨道时间结构体
	UTC_Orbit_Union:float2bit;
	UTC_Orbit_New:ULINT;
	UTC_Orbit_Last:ULINT;
	//拉偏变量
	TimeBias_Union:float2bit;
	Bias1_Union:float2bit;
	Bias2_Union:float2bit;
	Bias3_Union:float2bit;
	AcuElOffset:float2bit;
	rTimeBias:LREAL;
	rBias_1:LREAL;
	rBias_2:LREAL;
	rBias_3:LREAL;
	lrElOffset:LREAL;
	UTC_New:ULINT;
	UTC_Last:ULINT;
	aUTC_TIME:ARRAY [1..10] OF ULINT;  //用于三次样条插值的数据
	aPosCmd_1 :ARRAY [1..10] OF LREAL;//用于三次样条插值的数据
	aPosCmd_2 :ARRAY [1..10] OF LREAL;//用于三次样条插值的数据
	isave:INT;
	iCheck:INT;
	bPass:BOOL;//通过大小检测
	iclear:INT;

	uPTPTime_Union:float2bit;
	DI1_Union:Util.BIT_AS_WORD;	//上报位置结构体
	DI2_Union:Util.BIT_AS_WORD;
	DO1_Union:Util.BIT_AS_WORD;
	DO2_Union:Util.BIT_AS_WORD;
	DI1_word:WORD;
	DI2_word:WORD;
	DO1_word:WORD;
	DO2_word:WORD;
// 	
	PosSub1_Union:float2bit;
	PosSub2_Union:float2bit;
	PosSub3_Union:float2bit;
	BiasSub1_Union:float2bit;
	BiasSub2_Union:float2bit;
	BiasSub3_Union:float2bit;

	Chan_Union:Util.BIT_AS_WORD;
	Chan_word:WORD;

	ptptime:ULINT;

	rAzTheory:LREAL;
	rEltheory:LREAL;
	rAzTheory_Union:float2bit;
	rEltheory_Union:float2bit;


	MillisecondsTime: ULINT;

	// for time test
	DeltaTimeBetPC : ULINT;

	AGC_Value: REAL;

	// 方位轨道多项式变量
	starttime : LREAL ;
	rNodeTime1_az : LREAL;
	rNodeTime2_az : LREAL;
	rNodeTime3_az : LREAL;
    rNodeTime4_az : LREAL;
    rNodeTime5_az : LREAL;
	rEndTime : LREAL;

	lrFun1_az : ARRAY[0..10] OF LREAL;
    lrFun2_az : ARRAY[0..10] OF LREAL;
    lrFun3_az : ARRAY[0..10] OF LREAL;
    lrFun4_az : ARRAY[0..10] OF LREAL;
	lrFun5_az : ARRAY[0..10] OF LREAL;
    lrFun6_az : ARRAY[0..10] OF LREAL;

    unionFun1_az : ARRAY[0..10] OF UnionLREAL_WORD;
    unionFun2_az : ARRAY[0..10] OF UnionLREAL_WORD;
    unionFun3_az : ARRAY[0..10] OF UnionLREAL_WORD;
    unionFun4_az : ARRAY[0..10] OF UnionLREAL_WORD;
    unionFun5_az : ARRAY[0..10] OF UnionLREAL_WORD;
    unionFun6_az : ARRAY[0..10] OF UnionLREAL_WORD;

	unionStartTime: UnionLREAL_WORD;

    unionNodeTime1_az : UnionLREAL_WORD;
    unionNodeTime2_az : UnionLREAL_WORD;
    unionNodeTime3_az : UnionLREAL_WORD;
    unionNodeTime4_az : UnionLREAL_WORD;
    unionNodeTime5_az : UnionLREAL_WORD;
    unionEndTime : UnionLREAL_WORD;

	// 俯仰轨道多项式变量
	rNodeTime1_el : REAL;
	rNodeTime2_el : REAL;
	rNodeTime3_el : REAL;
    rNodeTime4_el : REAL;
    rNodeTime5_el : REAL;
	lrFun1_el : ARRAY[0..10] OF LREAL;
    lrFun2_el : ARRAY[0..10] OF LREAL;
    lrFun3_el : ARRAY[0..10] OF LREAL;
    lrFun4_el : ARRAY[0..10] OF LREAL;
	lrFun5_el : ARRAY[0..10] OF LREAL;
    lrFun6_el : ARRAY[0..10] OF LREAL;
	unionFun1_el : ARRAY[0..10] OF UnionLREAL_WORD;
	unionFun2_el : ARRAY[0..10] OF UnionLREAL_WORD;
	unionFun3_el : ARRAY[0..10] OF UnionLREAL_WORD;
	unionFun4_el : ARRAY[0..10] OF UnionLREAL_WORD;
	unionFun5_el : ARRAY[0..10] OF UnionLREAL_WORD;
	unionFun6_el : ARRAY[0..10] OF UnionLREAL_WORD;
	unionNodeTime1_el : UnionLREAL_WORD;
	unionNodeTime2_el : UnionLREAL_WORD;
	unionNodeTime3_el : UnionLREAL_WORD;
	unionNodeTime4_el : UnionLREAL_WORD;
	unionNodeTime5_el : UnionLREAL_WORD;
	unionSum:UnionLREAL_WORD;
	lrSum:LREAL;
	lrSumlocal:LREAL;
	i : INT;
	bNotFirst : BOOL; //
	bCheck : BOOL;
	bIFPoly: BOOL;//开启多项式拟合模式的标识，由上位机下发
	iCountPolyGet:INT;//计时接收多项式数组的模块
	uChangeTest:Time2Word;//变量转换测试
	iCountSum:INT;
	bSearch: BOOL;
	bStartTrackAcu : BOOL;

	//接收上位机下发位置模式速度
	rAzPosVel : REAL := 8;
	rElPosVel : REAL := 6;
	rTlPosVel : REAL := 8;
END_VAR
IF isInit=FALSE THEN							

	modtcpslaveinit(en_in:=TRUE,					//Modbus TCP Slave初始化功能块使能
	xenable:=TRUE,									//使能初始化功能
	iport:=502,										//开放端口号502
	en_out=>eout,									//Modbus TCP Slave初始化功能块执行完成
	isocket=>iSocket,								//创建的socket存入变量
	uierror=>uiErr);								//Modbus TCP Slave初始化功能块执行错误信息

	IF isocket>=0 AND uiErr=0 THEN					//成功创建socket且无错误，逻辑标志置位，下周期执行ELSE
		isInit:=TRUE;	

		enCtr:=FALSE;
		ELSE                                        //等待连接成功
		modtcpslaveinit(en_in:=0,xenable:=0);	
	END_IF


ELSE

	modtcpslavectrl(en_in:=enCtr,					//Modbus TCP Slave执行功能块使能
	xenable:=TRUE,									//Modbus TCP Slave执行功能使能
	isocket:=isocket,								//输入创建的socket
	dwatchdogtime:=2000,							//看门狗时间
	p_clientsocket:=ADR(arClient),					//将连接进来的socket存放到数组
	imaxclientcount:=10,							//设置最大连接数量
	uido_number:=10,uido_startaddr:=0,pdo_data:=ADR(ardo_data),		//uido_number设定线圈个数，uido_startaddr设定线圈起始地址，数据存放在ardo_data数组
	uidi_number:=10,uidi_startaddr:=0,pdi_data:=ADR(ardi_data),		//uidi_number设定离散型数据个数，uidi_startaddr设定离散型数据起始地址，数据存放在ardi_data数组
	uireg_number:=655,uireg_startaddr:=0,preg_data:=ADR(modbusData), //uireg_number设定保持型寄存器个数，uireg_startaddr设定保持型寄存器起始地址，数据存放在arreg_data数组
	uiai_number:=79,uiai_startaddr:=0,pai_data:=ADR(modbusInputRegs),//uiai_number设定输入型寄存器个数，uiai_startaddr设定输入型寄存器起始地址，数据存放在arai_data数组
	en_out=>eout,									//Modbus TCP Slave执行功能块执行完成
	uierror=>uierr);								//Modbus TCP Slave执行功能块执行错误信息
	enctr:=TRUE;
	IF uierr <>0 THEN                               //如果从站报错，则重新连接从站
		modtcpslaveinit(en_in:=0,xenable:=0);	
		isInit:=0;
	END_IF
	//iMode:  0 下电  1 上电  2 速度模式  3 停止  4 位置模式  5 继续运行
	//方位轴指令
(*
	Az_ctrl.iMode:=WORD_TO_INT(modbusData[0]);
	AZ_ctrl.rTarVel:=WORD_TO_REAL(modbusData[1]);
	AZ_ctrl.rTarPos:=WORD_TO_REAL(modbusData[2])*-1.0;

	//俯仰轴指令
	El_ctrl.iMode:=WORD_TO_INT(modbusData[10]);
	El_ctrl.rTarVel:=WORD_TO_REAL(modbusData[11]);
	El_ctrl.rTarPos:=WORD_TO_REAL(modbusData[12])+90.0;
	*)

	// modbus下发数据
	UTC_Union.Apart_word[1]:=modbusData[3];
	UTC_Union.Apart_word[2]:=modbusData[2];
	UTC_Union.Apart_word[3]:=modbusData[1];
	UTC_Union.Apart_word[4]:=modbusData[0];
	UTC_New:=UTC_Union.Apart_ulint;
	DeltaTimeBetPC := UTC_New - TO_ULINT(GVL.dRealTime);
	CtrlBool(W:=modbusData[7],
			B14=>bCommReset,
			B13=>Axis2Remote.bPIDEnable,
			B12=>Axis1Remote.bPIDEnable,
			B11=>Axis3Remote.bPIDEnable,
			B10=>bStartTrackAcu,
			B07=>bIFPoly,
			B06=>bSearch, //十字搜索开启标识
			);
	//方位轴指令
	iMode_2:=WORD_TO_INT(modbusData[8]);
	Pos2_Union.Apart_word[2]:=modbusData[9];
	Pos2_Union.Apart_word[1]:=modbusData[10];
	rPosCmd_2:=DINT_TO_LREAL( DWORD_TO_DINT( Pos2_Union.Apart_dword[1]))/100000*-1;
	rVelcmd_2:=DINT_TO_LREAL( WORD_TO_INT(modbusData[11]))/1000*-1;
	rP_2:=INT_TO_LREAL(WORD_TO_INT(modbusData[12]))/1000;
	rI_2:=INT_TO_LREAL(WORD_TO_INT(modbusData[13]))/1000;
	rD_2:=INT_TO_LREAL(WORD_TO_INT(modbusData[14]))/1000;
	rThreshold_2:=WORD_TO_INT(modbusData[15])/1000;
	rAcceleration_2:=INT_TO_LREAL(WORD_TO_INT(modbusData[16]))/1000;
	rDeceleration_2:=INT_TO_LREAL(WORD_TO_INT(modbusData[17]))/1000;
	rVelLim_2:=INT_TO_LREAL(WORD_TO_INT(modbusData[18]))/1000;

	//俯仰轴指令
	iMode_1:=WORD_TO_INT(modbusData[19]);
	Pos1_Union.Apart_word[2]:=modbusData[20];
	Pos1_Union.Apart_word[1]:=modbusData[21];
	rPosCmd_1:=DINT_TO_LREAL( DWORD_TO_DINT( Pos1_Union.Apart_dword[1]))/100000+90;
	rVelcmd_1:=DINT_TO_LREAL( WORD_TO_INT(modbusData[22]))/1000;
	rP_1:=INT_TO_LREAL(WORD_TO_INT(modbusData[23]))/1000;
	rI_1:=INT_TO_LREAL(WORD_TO_INT(modbusData[24]))/1000;
	rD_1:=INT_TO_LREAL(WORD_TO_INT(modbusData[25]))/1000;
	rThreshold_1:=WORD_TO_INT(modbusData[26])/1000;
	rAcceleration_1:=INT_TO_LREAL(WORD_TO_INT(modbusData[27]))/1000;
	rDeceleration_1:=INT_TO_LREAL(WORD_TO_INT(modbusData[28]))/1000;
	rVelLim_1:=INT_TO_LREAL(WORD_TO_INT(modbusData[29]))/1000;

	//倾斜轴指令
	iMode_3:=WORD_TO_INT(modbusData[30]);
	Pos3_Union.Apart_word[2]:=modbusData[31];
	Pos3_Union.Apart_word[1]:=modbusData[32];
	rPosCmd_3:=DINT_TO_LREAL( DWORD_TO_DINT( Pos3_Union.Apart_dword[1]))/100000*-1;
	rVelcmd_3:=DINT_TO_LREAL( WORD_TO_INT(modbusData[33]))/1000*-1;
	rP_3:=INT_TO_LREAL(WORD_TO_INT(modbusData[34]))/1000;
	rI_3:=INT_TO_LREAL(WORD_TO_INT(modbusData[35]))/1000;
	rD_3:=INT_TO_LREAL(WORD_TO_INT(modbusData[36]))/1000;
	rThreshold_3:=WORD_TO_INT(modbusData[37])/1000;
	rAcceleration_3:=INT_TO_LREAL(WORD_TO_INT(modbusData[38]))/1000;
	rDeceleration_3:=INT_TO_LREAL(WORD_TO_INT(modbusData[39]))/1000;


	//AGC锁定门限
	AGC_Value:=(WORD_TO_UDINT(modbusData[43])/100.0);
	GVL.Chanthreshold:=AGC_Value;

	//轨道时间
	UTC_Orbit_Union.Apart_word[1]:=modbusData[48];
	UTC_Orbit_Union.Apart_word[2]:=modbusData[47];
	UTC_Orbit_Union.Apart_word[3]:=modbusData[46];
	UTC_Orbit_Union.Apart_word[4]:=modbusData[45];
	UTC_Orbit_New:=UTC_Orbit_Union.Apart_ulint;
	//时间拉偏
	TimeBias_Union.Apart_word[1]:=modbusData[50];
	TimeBias_Union.Apart_word[2]:=modbusData[49];
	rTimeBias:=DINT_TO_LREAL( DWORD_TO_DINT( TimeBias_Union.Apart_dword[1]))/100000.0; //单位为秒
	IF rTimeBias>0.4 THEN//时间偏置最大限制 正负0.4秒
		rTimeBias:=0.4;
	ELSIF rTimeBias<-0.4 THEN
		rTimeBias:=-0.4;
	END_IF
	rTimeBias:=rTimeBias*1000000000;//秒转纳秒
	//两轴拉偏
	Bias2_Union.Apart_word[1]:=modbusData[52];
	Bias2_Union.Apart_word[2]:=modbusData[51];
	rBias_2:=DINT_TO_LREAL( DWORD_TO_DINT( Bias2_Union.Apart_dword[1]))/100000.0*(-1);

	Bias1_Union.Apart_word[1]:=modbusData[54];
	Bias1_Union.Apart_word[2]:=modbusData[53];
	rBias_1:=DINT_TO_LREAL( DWORD_TO_DINT( Bias1_Union.Apart_dword[1]))/100000.0;

	//俯仰零值
	AcuElOffset.Apart_word[1]:=modbusData[58];
	AcuElOffset.Apart_word[2]:=modbusData[57];
	lrElOffset:=DINT_TO_LREAL( DWORD_TO_DINT( AcuElOffset.Apart_dword[1]))/100000.0;
	//存储modbus时间序列和位置命令序列
	//IF UTC_New<>UTC_Last THEN //命令刷新，则更新序列


	//接受位置模式速度下发
	rAzPosVel:=INT_TO_LREAL(WORD_TO_INT(modbusData[61]))/1000.0;
	rElPosVel:=INT_TO_LREAL(WORD_TO_INT(modbusData[62]))/1000.0;
	rTlPosVel:=INT_TO_LREAL(WORD_TO_INT(modbusData[63]))/1000.0;

	IF rAzPosVel <= 16.0 THEN
		GVL.Axis2Remote.Pos_Vel := rAzPosVel;
	ELSE
		GVL.Axis2Remote.Pos_Vel := 16;
	END_IF

	IF rElPosVel <= 11.0 THEN
		GVL.Axis1Remote.Pos_Vel := rElPosVel;
	ELSE
		GVL.Axis1Remote.Pos_Vel := 11;
	END_IF

	IF rTlPosVel <= 8.0 THEN
		GVL.Axis3Remote.Pos_Vel := rTlPosVel;
	ELSE
		GVL.Axis3Remote.Pos_Vel := 8;
	END_IF

	FOR iCheck:=1 TO 10 DO
		IF UTC_Orbit_New>aUTC_TIME[iCheck] THEN
			bPass:=TRUE;
		ELSE
			bPass:=FALSE;
			EXIT;
		END_IF
	END_FOR
	IF bPass THEN //命令刷新，则更新序列
		FOR isave:=1 TO 9 DO
			aUTC_TIME[isave]:=aUTC_TIME[isave+1];
			aPosCmd_1[isave]:=aPosCmd_1[isave+1];
			aPosCmd_2[isave]:=aPosCmd_2[isave+1];
		END_FOR
		aUTC_TIME[10]:=UTC_Orbit_New;
		aPosCmd_1[10]:=rPosCmd_1;
		aPosCmd_2[10]:=rPosCmd_2;
	END_IF
	//若不是程引模式，则清空轨道时间数据
	IF Axis1Remote.iMode<>4 AND Axis2Remote.iMode<>4 THEN
		FOR iCheck:=1 TO 10 DO
			aUTC_TIME[iCheck]:=0;;
		END_FOR
	END_IF

	// modbus上报数据	
	IF icount<16#FFFF THEN
		icount:=icount+1;
	ELSE
		icount:=0;
	END_IF

	DI1_Union(B15:=SecurityCheck.bPrelimit_Positive_1,						//俯仰轴预限位--正 B15=0为未触发，B15=1为触发
			B14:=SecurityCheck.bFinallimit_1,								//俯仰轴终限位
			B13:=SecurityCheck.bPrelimit_Negative_1,						//俯仰轴预限位--负
			B12:=SecurityCheck.bFinallimit_1,								//俯仰位终限位
			B11:=SecurityCheck.bPrelimit_Positive_2,						//方位轴预限位--正
			B10:=SecurityCheck.bFinallimit_2,								//方位轴终限位
			B09:=SecurityCheck.bPrelimit_Negative_2,						//方位轴预限位--负
			B08:=SecurityCheck.bFinallimit_2,								//方位轴终限位
			B07:=FALSE,												//倾斜预限位--正
			B06:=FALSE,												//倾斜终限位--正
			B05:=FALSE,												//倾斜预限位--负
			B04:=FALSE,												//倾斜终限位--负
			B03:=FALSE,												//方位轴过零检测
			B02:=Axis2Status.bBrake,								//方位轴抱闸状态 0为解抱闸，1为抱闸
			B01:=Axis1Status.bBrake,								//俯仰轴抱闸状态
			B00:=Axis3Status.bBrake,								//倾斜轴抱闸状态
			W=>DI1_word	);

	DI2_Union(B15:=FALSE,								//
			B14:=FALSE,								//
			B13:=FALSE,
			B12:=FALSE,
			B11:=FALSE,
			B10:=FALSE,
			B09:=FALSE,
			B08:=FALSE,
			B07:=FALSE,
			B06:=FALSE,
			B05:=GVL.bError_Reset,											//错误复位符
			B04:=GVL.bLocalCtrl,											//本远控标识符
			B03:=FALSE,									//退限位标识符
			B02:=Axis2Remote.bPIDEnable,											//方位轴PID使能状态
			B01:=Axis1Remote.bPIDEnable,											//俯仰轴PID使能状态
			B00:=Axis3Remote.bPIDEnable,											//倾斜轴PID使能状态
			W=>DI2_word);
	DO1_Union(B15:=FALSE,								//中心体急停指示灯
			B14:=FALSE,							//声光报警		1为触发，0为未触发
			B13:=FALSE,							//爬梯急停指示灯 B13=1为亮 B13=0为灭
