/Device/Plc Logic/Application/插值模块/solve:
// 计算矩阵的行列式
Determinant := M[1, 1] * (M[2, 2] * M[3, 3] - M[2, 3] * M[3, 2]) -
               M[1, 2] * (M[2, 1] * M[3, 3] - M[2, 3] * M[3, 1]) +
               M[1, 3] * (M[2, 1] * M[3, 2] - M[2, 2] * M[3, 1]);

(*
// 计算3x3矩阵的伴随矩阵
Determinant := M[1, 1] * (M[2, 2] * M[3, 3] - M[2, 3] * M[3, 2]) -
               M[1, 2] * (M[2, 1] * M[3, 3] - M[2, 3] * M[3, 1]) +
               M[1, 3] * (M[2, 1] * M[3, 2] - M[2, 2] * M[3, 1]);

IF ABS(Determinant) > 1.0E-6 THEN
    FOR i := 1 TO 3 DO
        FOR j := 1 TO 3 DO
            AdjointMatrix[i, j] := M[(i MOD 3) + 1, (j MOD 3) + 1] * M[((i + 1) MOD 3) + 1, ((j + 1) MOD 3) + 1] -
                                   M[(i MOD 3) + 1, ((j + 1) MOD 3) + 1] * M[((i + 1) MOD 3) + 1, (j MOD 3) + 1];
        END_FOR
    END_FOR

    FOR i := 1 TO 3 DO
        FOR j := 1 TO 3 DO
            AdjointMatrix[j, i] := AdjointMatrix[i, j];
            AdjointMatrix[i, j] := AdjointMatrix[i, j] / Determinant;
        END_FOR
    END_FOR
END_IF
*)
// 计算3x3矩阵的伴随矩阵
Determinant := M[1, 1] * (M[2, 2] * M[3, 3] - M[2, 3] * M[3, 2]) -
               M[1, 2] * (M[2, 1] * M[3, 3] - M[2, 3] * M[3, 1]) +
               M[1, 3] * (M[2, 1] * M[3, 2] - M[2, 2] * M[3, 1]);

IF ABS(Determinant) > 1.0E-6 THEN
    FOR i := 1 TO 3 DO
        FOR j := 1 TO 3 DO
            AdjointMatrix[j, i] := ((M[(i MOD 3) + 1, (j MOD 3) + 1] * M[((i + 1) MOD 3) + 1, ((j + 1) MOD 3) + 1] -
                                   M[(i MOD 3) + 1, ((j + 1) MOD 3) + 1] * M[((i + 1) MOD 3) + 1, (j MOD 3) + 1]) / Determinant);
        END_FOR
    END_FOR
END_IF

// 计算X = AdjointMatrix * G
FOR i := 1 TO 3 DO
    X[i] := 0.0;
    FOR j := 1 TO 3 DO
        X[i] := X[i] + AdjointMatrix[i, j] * G[j];
    END_FOR
END_FOR

/Device/Plc Logic/Application/El_Ctrl_FB:
FUNCTION_BLOCK El_Ctrl_FB
VAR_INPUT
	sLocal:AxisCrtlStruct;
	sCtrl:AxisCrtlStruct;
	sStatus:AxisStatus;
	sVisible:AxisVisible;
	rRealPos:REAL;
	rPosLimK:REAL;
END_VAR
VAR_OUTPUT
	logicError:INT;
END_VAR
VAR
	VelPID_1:PID;
	VelPID_2:PID;
	VelPID_3:PID;
	vpid1:vpid;
	TON_0:TON;
	bTick:BOOL;
	tr:BOOL;
	icount1:INT := 0;
	icount2:INT := 0;
	icount3:INT := 0;
	bfin1:BOOL;
	bfin2:BOOL;
	istate:INT:=0;
	icount:INT:=0;
END_VAR

// 下电时复位控制字bit8
IF sStatus.Disabled OR (NOT sStatus.Moving) THEN
	bElCtrlBit8 := FALSE;
END_IF

//	错误复位功能
IF GVL.bError_Reset THEN
	sCtrl.iMode:=6;
	sLocal.iMode:=6;
	GVL.Error_code:=0;
END_IF
IF GVL.Error_code =0 THEN
	GVL.bError_Reset:=FALSE;
END_IF

/////////心跳报错清除/////////
IF GVL.eElErrorcode = 16#8130 AND NOT tr THEN
	GVL.bElCtrlBit7 := TRUE;
	tr:=TRUE;
	istate:=0;
	icount:=0;
	// 写入下电控制字
	GVL.bElCtrlBit3 := FALSE;
	GVL.bElCtrlBit0 := FALSE;
	GVL.bElCtrlBit1 := FALSE;
	GVL.bElCtrlBit2 := FALSE;	
END_IF
IF tr THEN
	icount1 := icount1 + 1;
END_IF
IF icount1 > 101 THEN
	icount1 := 0;
	tr := FALSE;
	GVL.bElCtrlBit7 := FALSE;
	bfin1 := TRUE;
END_IF
IF bfin1 THEN
	icount2 := icount2 + 1;
END_IF
IF icount2 > 101 THEN
	bfin1 := FALSE;
	icount2 := 0;
END_IF
//////////////////////////////

IF GVL.Error_code=0 AND GVL.eElErrorcode = 0 AND NOT GVL.bElCtrlBit7  AND NOT tr AND NOT bfin1 AND NOT bfin2 THEN
	IF GVL.bLocalCtrl=FALSE THEN //远控
		IF sCtrl.iMode <> 1 THEN
			istate:=0;
			icount:=0;
		END_IF
		CASE sCtrl.iMode OF
			MODES.powerOff: // 下电
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN // 运动中，先停止运动
						GVL.diElTargetVel := 0;
						bElCtrlBit8 := TRUE;
					ELSE
						// 写入下电控制字
						GVL.bElCtrlBit3 := FALSE;
						GVL.bElCtrlBit0 := FALSE;
						GVL.bElCtrlBit1 := FALSE;
						GVL.bElCtrlBit2 := FALSE;
					END_IF
				END_IF

				vpid1(rKpbase:=1, rKibase:=0.01, rKpMax:=1, rKiMax:=0.01, rVelThreshold:=10,rTarget:=sCtrl.rPIDCmdPos,rFeedback:=rRealPos,rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegitive:=sCtrl.rSoft_limit_Negative,
								bPIDEnable:=sCtrl.bPIDEnable,rVelLim:=sCtrl.rVel_Limit,rKpScale:=0.02,rKiScale:=0.005,rElPos:=GVL.rFctPosReal_1-90,
								iThrehold:=sCtrl.rPIDThre,rPIDOutDir=>sCtrl.rPIDCmdVel);
			MODES.powerOn:  // 上电
				IF sStatus.Disabled THEN
					// 目标速度清零
					GVL.diElTargetVel := 0;
					IF GVL.siElMode <> 3 THEN // 上电时模式默认为3，速度模式
						GVL.siElMode := 3;
					END_IF
					IF siElMode = 3 THEN
						CASE istate OF
							0:
								GVL.bElCtrlBit1 := TRUE;
								GVL.bElCtrlBit2 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=1;
								END_IF
							1:
								GVL.bElCtrlBit0 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=2;
								END_IF
							2:
								GVL.bElCtrlBit3 := TRUE;
						END_CASE
					END_IF
				ELSE
					IF sStatus.Moving THEN
						GVL.diElTargetVel := 0;
						bElCtrlBit8 := TRUE;
					ELSE
						bElCtrlBit8 := FALSE;
					END_IF
				END_IF
			MODES.positionMode: // 远控指向模式
				IF NOT sStatus.Disabled THEN
					IF sCtrl.bStartAutoTrack THEN
						//自跟踪模式下，由误差电压直接驱动
						VelPID_1(rTarget:=sCtrl.rChanU + rRealPos,
								rFeedback:=rRealPos,
								rPosLimPositive:=sCtrl.rSoft_limit_Postive,
								rPosLimNegative:=sCtrl.rSoft_limit_Negative,
								rVelLim:=sCtrl.rVel_Limit,
								rKp:=1,//自跟踪PI系数3,0.02
								rKi:=0,
								rKd:=0,
								bPIDEnable:=sCtrl.bPIDEnable,
								iThreshold:= -1,
								rPIDOutput=>sCtrl.rPIDCmdVel);							
					ELSE
						//PID计算速度指令
						VelPID_1(rTarget:=sCtrl.rPosCmd,
							rFeedback:=rRealPos,
							rVelLim:=sCtrl.Pos_Vel,
							rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegative:=sCtrl.rSoft_limit_Negative,
							rKp:=0.7,//程引PI系数地带：1,0.002  高带：3,0.02
							rKi:=0,
							rKd:=0,
							bPIDEnable:=sCtrl.bPIDEnable,
							iThreshold:=sCtrl.rPIDThre,
							rPIDOutput=>sCtrl.rPIDCmdVel);
					END_IF
					GVL.diElTargetVel := REAL_TO_DINT(sCtrl.rPIDCmdVel * 524288 / 360);
					GVL.diElTargetAcc := REAL_TO_UDINT(9 * 524288 / 360);   //加速度
					GVL.diElTargetDec := REAL_TO_UDINT(9 * 524288 / 360);   //减速度
				END_IF
			MODES.velocityMode://手控速度模式-远控模式
				IF NOT sStatus.Disabled THEN
					IF ABS(sCtrl.rVelCmd) <= sCtrl.rVel_Limit THEN
						GVL.diElTargetVel := REAL_TO_DINT(sCtrl.rVelCmd * 524288 / 360);
					ELSIF sCtrl.rVelCmd > sCtrl.rVel_Limit THEN
						GVL.diElTargetVel := REAL_TO_DINT(sCtrl.rVel_Limit * 524288 / 360);
					ELSE
						GVL.diElTargetVel := REAL_TO_DINT(-sCtrl.rVel_Limit * 524288 / 360);
					END_IF
					GVL.diElTargetAcc := REAL_TO_UDINT(sCtrl.rAcceleration * 524288 / 360);   //加速度
					GVL.diElTargetDec := REAL_TO_UDINT(sCtrl.rDeceleration * 524288 / 360);   //减速度
				END_IF
			MODES.programBootMode://PID速度模式-正常模式 程引
				IF NOT sStatus.Disabled THEN
					IF sCtrl.bStartAutoTrack THEN
						(*
						//自跟踪模式下，由误差电压直接驱动
						VelPID_3(rTarget:=sCtrl.rChanU + rRealPos,
								rFeedback:=rRealPos,
								rPosLimPositive:=sCtrl.rSoft_limit_Postive,
								rPosLimNegative:=sCtrl.rSoft_limit_Negative,
								rVelLim:=sCtrl.rVel_Limit,
								rKp:=sCtrl.rP_AutoTrack,//自跟踪PI系数3,0.02
								rKi:=sCtrl.rI_AutoTrack,
								rKd:=sCtrl.rD,
								bPIDEnable:=sCtrl.bPIDEnable,
								iThreshold:= -1,
								rPIDOutput=>sCtrl.rPIDCmdVel);	
								*)
						vpid1(rKpbase:=Persistentvars.rElKpBase, rKibase:=Persistentvars.rElKiBase, rKpMax:=Persistentvars.rElKpMax, rKiMax:=Persistentvars.rElKiMax, rVelThreshold:=Persistentvars.rElThre,rTarget:=sCtrl.rPIDCmdPos,rFeedback:=rRealPos,rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegitive:=sCtrl.rSoft_limit_Negative,
								bPIDEnable:=sCtrl.bPIDEnable,rVelLim:=sCtrl.rVel_Limit,rKpScale:=Persistentvars.rElKpscale,rKiScale:=Persistentvars.rElKiscale,rElPos:=GVL.rFctPosReal_1-90,
								iThrehold:=sCtrl.rPIDThre,rPIDOutDir=>sCtrl.rPIDCmdVel);						
					ELSE
						//PID计算速度指令
						(*
						VelPID_3(rTarget:=sCtrl.rPIDCmdPos,
							rFeedback:=rRealPos,
							rVelLim:=sCtrl.rVel_Limit,
							rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegative:=sCtrl.rSoft_limit_Negative,
							rKp:=sCtrl.rP,//程引PI系数地带：1,0.002  高带：3,0.02
							rKi:=sCtrl.rI,
							rKd:=sCtrl.rD,
							bPIDEnable:=sCtrl.bPIDEnable,
							iThreshold:=sCtrl.rPIDThre,
							rPIDOutput=>);
							*)
						vpid1(rKpbase:=Persistentvars.rElKpBase, rKibase:=Persistentvars.rElKiBase, rKpMax:=Persistentvars.rElKpMax, rKiMax:=Persistentvars.rElKiMax, rVelThreshold:=Persistentvars.rElThre,rTarget:=sCtrl.rPIDCmdPos,rFeedback:=rRealPos,rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegitive:=sCtrl.rSoft_limit_Negative,
								bPIDEnable:=sCtrl.bPIDEnable,rVelLim:=sCtrl.rVel_Limit,rKpScale:=Persistentvars.rElKpscale,rKiScale:=Persistentvars.rElKiscale,rElPos:=GVL.rFctPosReal_1-90,
								iThrehold:=sCtrl.rPIDThre,rPIDOutDir=>sCtrl.rPIDCmdVel);
					END_IF
					GVL.diElTargetVel := REAL_TO_DINT(sCtrl.rPIDCmdVel * 524288 / 360);
					GVL.diElTargetAcc := REAL_TO_UDINT(sCtrl.rAcceleration * 524288 / 360);   //加速度
					GVL.diElTargetDec := REAL_TO_UDINT(sCtrl.rDeceleration * 524288 / 360);   //减速度
				END_IF
			MODES.reset://重置
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diElTargetVel := 0;
						bElCtrlBit8 := TRUE;
					ELSE
						bElCtrlBit8 := FALSE;
					END_IF
				END_IF
			MODES.halt://待机
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diElTargetVel := 0;
						bElCtrlBit8 := TRUE;
					ELSE
						bElCtrlBit8 := FALSE;
					END_IF
				END_IF

		END_CASE
	ELSE // 本控
		IF sLocal.iMode <> 1 THEN
			istate:=0;
			icount:=0;
		END_IF
		CASE sLocal.iMode OF
			MODES.powerOff: // 下电
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN // 运动中，先停止运动
						GVL.diElTargetVel := 0;
						bElCtrlBit8 := TRUE;
					ELSE
						// 写入下电控制字
						GVL.bElCtrlBit3 := FALSE;
						GVL.bElCtrlBit0 := FALSE;
						GVL.bElCtrlBit1 := FALSE;
						GVL.bElCtrlBit2 := FALSE;
					END_IF
				END_IF
			MODES.powerOn:  // 上电
				IF sStatus.Disabled THEN
					// 目标速度清零
					GVL.diElTargetVel := 0;
					IF GVL.siElMode <> 3 THEN // 上电时模式默认为3，速度模式
						GVL.siElMode := 3;
					END_IF
					IF siElMode = 3 THEN



						CASE istate OF
							0:
								GVL.bElCtrlBit1 := TRUE;
								GVL.bElCtrlBit2 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=1;
								END_IF
							1:
								GVL.bElCtrlBit0 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=2;
								END_IF
							2:
								GVL.bElCtrlBit3 := TRUE;
						END_CASE
					END_IF
				ELSE
					IF sStatus.Moving THEN
						GVL.diElTargetVel := 0;
						bElCtrlBit8 := TRUE;
					ELSE
						bElCtrlBit8 := FALSE;
					END_IF
				END_IF
			MODES.velocityMode://手控速度模式-本控模式
				IF NOT sStatus.Disabled THEN
					IF ABS(sLocal.rVelCmd) <= sLocal.rVel_Limit THEN
						GVL.diElTargetVel := REAL_TO_DINT(sLocal.rVelCmd * 524288 / 360);
					ELSIF sLocal.rVelCmd > sLocal.rVel_Limit THEN
						GVL.diElTargetVel := REAL_TO_DINT(sLocal.rVel_Limit * 524288 / 360);
					ELSE
						GVL.diElTargetVel := REAL_TO_DINT(-sLocal.rVel_Limit * 524288 / 360);
					END_IF
					GVL.diElTargetAcc := REAL_TO_UDINT(sLocal.rAcceleration * 524288 / 360);   //加速度
					GVL.diElTargetDec := REAL_TO_UDINT(sLocal.rDeceleration * 524288 / 360);   //减速度
				END_IF
			MODES.programBootMode://本控位置模式
				IF NOT sStatus.Disabled THEN
					IF NOT sLocal.bPIDEnable THEN
						GVL.diElTargetVel := 0;							
					ELSE
						IF NOT slocal.bStartAutoTrack THEN
							//PID计算速度指令
							 VelPID_2(rTarget:=sLocal.rPosCmd,
									 rFeedback:=rRealPos,
									 rPosLimPositive:=sLocal.rSoft_limit_Postive,//软限位
									 rPosLimNegative:=sLocal.rSoft_limit_Negative,
									 rKp:=0.7,
									 rKi:=0,
									 rKd:=0,
									 iThreshold:=sLocal.rPIDThre,
									 bPIDEnable:=sLocal.bPIDEnable,
									 rVelLim:=sLocal.Pos_Vel,
									 rPIDOutput=>sLocal.rPIDCmdVel);//普通PID
						ELSE
							 VelPID_2(rTarget:=sLocal.rChanU + rRealPos,
								rFeedback:=rRealPos,
								rPosLimPositive:=sLocal.rSoft_limit_Postive,
								rPosLimNegative:=sLocal.rSoft_limit_Negative,
								rVelLim:=sLocal.rVel_Limit,
								rKp:=1,//自跟踪PI系数3,0.02
								rKi:=0,
								rKd:=0,
								bPIDEnable:=sLocal.bPIDEnable,
								iThreshold:= -1,
								rPIDOutput=>sLocal.rPIDCmdVel);
						END_IF

					END_IF
					GVL.diElTargetVel := REAL_TO_DINT(sLocal.rPIDCmdVel * 524288 / 360);
					GVL.diElTargetAcc := REAL_TO_UDINT(9 * 524288 / 360);   //加速度
					GVL.diElTargetDec := REAL_TO_UDINT(9 * 524288 / 360);   //减速度
				END_IF
			MODES.reset://重置
			// 是否需要
			MODES.halt://待机
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diElTargetVel := 0;
						bElCtrlBit8 := TRUE;
					ELSE
						bElCtrlBit8 := FALSE;
					END_IF
				END_IF

		END_CASE
	END_IF
ELSIF GVL.Error_code<>0 AND GVL.eElErrorcode = 0 AND NOT GVL.bElCtrlBit7  AND NOT tr AND NOT bfin1 AND NOT bfin2 THEN
	// 出现错误，轴停止运动
	GVL.diElTargetVel := 0;
	bElCtrlBit8 := TRUE;
	TON_0(IN:=bElCtrlBit8,PT:=T#1S,Q=>,ET=>);//判断stop0执行是否超时,若超时强制下电（手动复位）
	IF TON_0.Q THEN
		bTick:=TRUE;
	END_IF
	IF bTick AND sStatus.Moving THEN // 超时强制下电
		// 写入下电控制字
		GVL.bElCtrlBit3 := FALSE;
		GVL.bElCtrlBit0 := FALSE;
		GVL.bElCtrlBit1 := FALSE;
		GVL.bElCtrlBit2 := FALSE;
	END_IF
END_IF

/Device/Plc Logic/Application/Az_Ctrl_FB:
FUNCTION_BLOCK Az_Ctrl_FB
VAR_INPUT
	sLocal:AxisCrtlStruct;
	sCtrl:AxisCrtlStruct;
	sStatus:AxisStatus;
	sVisible:AxisVisible;
	rRealPos:REAL;
	rPosLimK:REAL;
END_VAR
VAR_OUTPUT
	logicError:INT;
END_VAR
VAR
	VelPID_1:PID;
	VelPID_2:PID;
	VelPID_3:PID;
	vpid1:vpid;
	TON_0:TON;
	bTick:BOOL;
	tr:BOOL;
	icount1:INT := 0;
	icount2:INT := 0;
	icount3:INT := 0;
	bfin1:BOOL;
	bfin2:BOOL;
	istate:INT:=0;
	icount:INT:=0;
END_VAR

// 下电时复位控制字bit8
IF sStatus.Disabled OR(NOT sStatus.Moving)THEN
	bAzCtrlBit8 := FALSE;
END_IF

//	错误复位功能
IF GVL.bError_Reset THEN
	sCtrl.iMode:=6;
	sLocal.iMode:=6;
	GVL.Error_code:=0;
END_IF
IF GVL.Error_code =0 THEN
	GVL.bError_Reset:=FALSE;
END_IF

/////////心跳报错清除/////////
IF GVL.eAzErrorcode = 16#8130 AND NOT tr THEN
	GVL.bAzCtrlBit7 := TRUE;
	tr:=TRUE;
	istate:=0;
	icount:=0;
	// 写入下电控制字
	GVL.bAzCtrlBit3 := FALSE;
	GVL.bAzCtrlBit0 := FALSE;
	GVL.bAzCtrlBit1 := FALSE;
	GVL.bAzCtrlBit2 := FALSE;
END_IF
IF tr THEN
	icount1 := icount1 + 1;
END_IF
IF icount1 > 101 THEN
	icount1 := 0;
	tr := FALSE;
	GVL.bAzCtrlBit7 := FALSE;
	bfin1 := TRUE;
END_IF
IF bfin1 THEN
	icount2 := icount2 + 1;
END_IF
IF icount2 > 101 THEN
	bfin1 := FALSE;
	icount2 := 0;
END_IF
/////////////////////////////

IF GVL.Error_code=0 AND GVL.eAzErrorcode = 0 AND NOT GVL.bAzCtrlBit7  AND NOT tr AND NOT bfin1 AND NOT bfin2 THEN
	IF GVL.bLocalCtrl=FALSE THEN //远控
		IF sCtrl.iMode <> 1 THEN
			istate:=0;
			icount:=0;
		END_IF
		CASE sCtrl.iMode OF
			MODES.powerOff: // 下电
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN // 运动中，先停止运动
						GVL.diAzTargetVel := 0;
						bAzCtrlBit8 := TRUE;
					ELSE
						// 写入下电控制字
						GVL.bAzCtrlBit3 := FALSE;
						GVL.bAzCtrlBit0 := FALSE;
						GVL.bAzCtrlBit1 := FALSE;
						GVL.bAzCtrlBit2 := FALSE;
					END_IF
				END_IF

				vpid1(rKpbase:=1, rKibase:=0.01, rKpMax:=1, rKiMax:=0.01, rVelThreshold:=10,rTarget:=sCtrl.rPIDCmdPos,rFeedback:=rRealPos,rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegitive:=sCtrl.rSoft_limit_Negative,
								bPIDEnable:=sCtrl.bPIDEnable,rVelLim:=sCtrl.rVel_Limit,rKpScale:=0.02,rKiScale:=0.005,rElPos:=GVL.rFctPosReal_1-90,
								iThrehold:=sCtrl.rPIDThre,rPIDOutDir=>sCtrl.rPIDCmdVel);
			MODES.powerOn:  // 上电
				IF sStatus.Disabled THEN
					// 目标速度清零
					GVL.diAzTargetVel := 0;
					IF GVL.siAzMode <> 3 THEN // 上电时模式默认为3，速度模式
						GVL.siAzMode := 3;
					END_IF
					IF siAzMode = 3 THEN
						CASE istate OF
							0:
								GVL.bAzCtrlBit1 := TRUE;
								GVL.bAzCtrlBit2 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=1;
								END_IF
							1:
								GVL.bAzCtrlBit0 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=2;
								END_IF
							2:
								GVL.bAzCtrlBit3 := TRUE;
						END_CASE
					END_IF
				ELSE
					IF sStatus.Moving THEN
						GVL.diAzTargetVel := 0;
						bAzCtrlBit8 := TRUE;
					ELSE
						bAzCtrlBit8 := FALSE;
					END_IF
				END_IF
			MODES.positionMode: // 远控指向模式
				IF NOT sStatus.Disabled THEN
					IF sCtrl.bStartAutoTrack THEN
						//自跟踪模式下，由误差电压直接驱动
						VelPID_1(rTarget:=sCtrl.rChanU + rRealPos,
								rFeedback:=rRealPos,
								rPosLimPositive:=sCtrl.rSoft_limit_Postive,
								rPosLimNegative:=sCtrl.rSoft_limit_Negative,
								rVelLim:=sCtrl.rVel_Limit,
								rKp:=1,//自跟踪PI系数3,0.02
								rKi:=0,
								rKd:=0,
								bPIDEnable:=sCtrl.bPIDEnable,
								iThreshold:= -1,
								rPIDOutput=>sCtrl.rPIDCmdVel);							
					ELSE
						//PID计算速度指令
						VelPID_1(rTarget:=sCtrl.rPosCmd,
							rFeedback:=rRealPos,
							rVelLim:=sCtrl.Pos_Vel,
							rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegative:=sCtrl.rSoft_limit_Negative,
							rKp:=0.6,//程引PI系数低带：1,0.002  高带：3,0.02
							rKi:=0,
							rKd:=0,
							bPIDEnable:=sCtrl.bPIDEnable,
							iThreshold:=sCtrl.rPIDThre,
							rPIDOutput=>sCtrl.rPIDCmdVel);
					END_IF
					GVL.diAzTargetVel := REAL_TO_DINT(sCtrl.rPIDCmdVel * 524288 / 360);
					GVL.diAzTargetAcc := REAL_TO_UDINT(12 * 524288 / 360);   //加速度
					GVL.diAzTargetDec := REAL_TO_UDINT(12 * 524288 / 360);   //减速度
				END_IF
			MODES.velocityMode://手控速度模式-远控模式
				IF NOT sStatus.Disabled THEN
					IF ABS(sCtrl.rVelCmd) <= sCtrl.rVel_Limit THEN
						GVL.diAzTargetVel := REAL_TO_DINT(sCtrl.rVelCmd * 524288 / 360);
					ELSIF sCtrl.rVelCmd > sCtrl.rVel_Limit THEN
						GVL.diAzTargetVel := REAL_TO_DINT(sCtrl.rVel_Limit * 524288 / 360);
					ELSE
						GVL.diAzTargetVel := REAL_TO_DINT(-sCtrl.rVel_Limit * 524288 / 360);
					END_IF
					GVL.diAzTargetAcc := REAL_TO_UDINT(sCtrl.rAcceleration * 524288 / 360);   //加速度
					GVL.diAzTargetDec := REAL_TO_UDINT(sCtrl.rDeceleration * 524288 / 360);   //减速度
				END_IF
			MODES.programBootMode://PID速度模式-正常模式 程引
				IF NOT sStatus.Disabled THEN
					IF sCtrl.bStartAutoTrack THEN
						(*
						//自跟踪模式下，由误差电压直接驱动
						VelPID_3(rTarget:=sCtrl.rChanU + rRealPos,
								rFeedback:=rRealPos,
								rPosLimPositive:=sCtrl.rSoft_limit_Postive,
								rPosLimNegative:=sCtrl.rSoft_limit_Negative,
								rVelLim:=sCtrl.rVel_Limit,
								rKp:=sCtrl.rP_AutoTrack,//自跟踪PI系数3,0.02
								rKi:=sCtrl.rI_AutoTrack,
								rKd:=sCtrl.rD,
								bPIDEnable:=sCtrl.bPIDEnable,
								iThreshold:= -1,
								rPIDOutput=>sCtrl.rPIDCmdVel);
								*)
						vpid1(rKpbase:=Persistentvars.rAzKpBase, rKibase:=Persistentvars.rAzKiBase, rKpMax:=Persistentvars.rAzKpMax, rKiMax:=Persistentvars.rAzKiMax, rVelThreshold:=Persistentvars.rAzThre,rTarget:=sCtrl.rPIDCmdPos,rFeedback:=rRealPos,rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegitive:=sCtrl.rSoft_limit_Negative,
								bPIDEnable:=sCtrl.bPIDEnable,rVelLim:=sCtrl.rVel_Limit,rKpScale:=Persistentvars.rAzKpscale,rKiScale:=Persistentvars.rAzKiscale,rElPos:=GVL.rFctPosReal_1-90,
								iThrehold:=sCtrl.rPIDThre,rPIDOutDir=>sCtrl.rPIDCmdVel);							
					ELSE
						//PID计算速度指令
						(*
						VelPID_3(rTarget:=sCtrl.rPIDCmdPos,
							rFeedback:=rRealPos,
							rVelLim:=sCtrl.rVel_Limit,
							rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegative:=sCtrl.rSoft_limit_Negative,
							rKp:=sCtrl.rP,//程引PI系数地带：1,0.002  高带：3,0.02
							rKi:=sCtrl.rI,
							rKd:=sCtrl.rD,
							bPIDEnable:=sCtrl.bPIDEnable,
							iThreshold:=sCtrl.rPIDThre,
							rPIDOutput=>);
							*)
						vpid1(rKpbase:=Persistentvars.rAzKpBase, rKibase:=Persistentvars.rAzKiBase, rKpMax:=Persistentvars.rAzKpMax, rKiMax:=Persistentvars.rAzKiMax, rVelThreshold:=Persistentvars.rAzThre,rTarget:=sCtrl.rPIDCmdPos,rFeedback:=rRealPos,rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegitive:=sCtrl.rSoft_limit_Negative,
								bPIDEnable:=sCtrl.bPIDEnable,rVelLim:=sCtrl.rVel_Limit,rKpScale:=Persistentvars.rAzKpscale,rKiScale:=Persistentvars.rAzKiscale,rElPos:=GVL.rFctPosReal_1-90,
								iThrehold:=sCtrl.rPIDThre,rPIDOutDir=>sCtrl.rPIDCmdVel);

					END_IF
					GVL.diAzTargetVel := REAL_TO_DINT(sCtrl.rPIDCmdVel * 524288 / 360);
					GVL.diAzTargetAcc := REAL_TO_UDINT(sCtrl.rAcceleration * 524288 / 360);   //加速度
					GVL.diAzTargetDec := REAL_TO_UDINT(sCtrl.rDeceleration * 524288 / 360);   //减速度
				END_IF
			MODES.reset://重置
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diAzTargetVel := 0;
						bAzCtrlBit8 := TRUE;
					ELSE
						bAzCtrlBit8 := FALSE;
					END_IF
				END_IF
			MODES.halt://待机
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diAzTargetVel := 0;
						bAzCtrlBit8 := TRUE;
					ELSE
						bAzCtrlBit8 := FALSE;
					END_IF
				END_IF

		END_CASE
	ELSE // 本控
		IF sLocal.iMode <> 1 THEN
			istate:=0;
			icount:=0;
		END_IF
		CASE sLocal.iMode OF
			MODES.powerOff: // 下电
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN // 运动中，先停止运动
						GVL.diAzTargetVel := 0;
						bAzCtrlBit8 := TRUE;
					ELSE
						// 写入下电控制字
						GVL.bAzCtrlBit3 := FALSE;
						GVL.bAzCtrlBit0 := FALSE;
						GVL.bAzCtrlBit1 := FALSE;
						GVL.bAzCtrlBit2 := FALSE;
					END_IF
				END_IF
			MODES.powerOn:  // 上电
				IF sStatus.Disabled THEN
					// 目标速度清零
					GVL.diAzTargetVel := 0;
					IF GVL.siAzMode <> 3 THEN // 上电时模式默认为3，速度模式
						GVL.siAzMode := 3;
					END_IF
					IF siAzMode = 3 THEN
						CASE istate OF
							0:
								GVL.bAzCtrlBit1 := TRUE;
								GVL.bAzCtrlBit2 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=1;
								END_IF
							1:
								GVL.bAzCtrlBit0 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=2;
								END_IF
							2:
								GVL.bAzCtrlBit3 := TRUE;
						END_CASE
					END_IF
				ELSE
					IF sStatus.Moving THEN
						GVL.diAzTargetVel := 0;
						bAzCtrlBit8 := TRUE;
					ELSE
						bAzCtrlBit8 := FALSE;
					END_IF
				END_IF
			MODES.velocityMode://手控速度模式-本控模式
				IF NOT sStatus.Disabled THEN
					IF ABS(sLocal.rVelCmd) <= sLocal.rVel_Limit THEN
						GVL.diAzTargetVel := REAL_TO_DINT(sLocal.rVelCmd * 524288 / 360);
					ELSIF sLocal.rVelCmd > sLocal.rVel_Limit THEN
						GVL.diAzTargetVel := REAL_TO_DINT(sLocal.rVel_Limit * 524288 / 360);
					ELSE
						GVL.diAzTargetVel := REAL_TO_DINT(-sLocal.rVel_Limit * 524288 / 360);
					END_IF
					GVL.diAzTargetAcc := REAL_TO_UDINT(sLocal.rAcceleration * 524288 / 360);   //加速度
					GVL.diAzTargetDec := REAL_TO_UDINT(sLocal.rDeceleration * 524288 / 360);   //减速度
				END_IF
			MODES.programBootMode://本控位置模式
				IF NOT sStatus.Disabled THEN
					IF NOT sLocal.bPIDEnable THEN
						GVL.diAzTargetVel := 0;							
					ELSE
						IF NOT slocal.bStartAutoTrack THEN
							//PID计算速度指令
							 VelPID_2(rTarget:=sLocal.rPosCmd,
									 rFeedback:=rRealPos,
									 rPosLimPositive:=sLocal.rSoft_limit_Postive,//软限位
									 rPosLimNegative:=sLocal.rSoft_limit_Negative,
									 rKp:=0.6,
									 rKi:=0,
									 rKd:=0,
									 iThreshold:=sLocal.rPIDThre,
									 bPIDEnable:=sLocal.bPIDEnable,
									 rVelLim:=sLocal.Pos_Vel,
									 rPIDOutput=>sLocal.rPIDCmdVel);//普通PID
						ELSE
							//PID计算速度指令
							 VelPID_2(rTarget:=sLocal.rChanU + rRealPos,
								rFeedback:=rRealPos,
								rPosLimPositive:=sLocal.rSoft_limit_Postive,
								rPosLimNegative:=sLocal.rSoft_limit_Negative,
								rVelLim:=sLocal.rVel_Limit,
								rKp:=1,//自跟踪PI系数3,0.02
								rKi:=0,
								rKd:=0,
								bPIDEnable:=sLocal.bPIDEnable,
								iThreshold:= -1,
								rPIDOutput=>sLocal.rPIDCmdVel);//普通PID
						END_IF

					END_IF
					GVL.diAzTargetVel := REAL_TO_DINT(sLocal.rPIDCmdVel * 524288 / 360);
					GVL.diAzTargetAcc := REAL_TO_UDINT(12 * 524288 / 360);   //加速度
					GVL.diAzTargetDec := REAL_TO_UDINT(12 * 524288 / 360);   //减速度
				END_IF
			MODES.reset://重置
			// 是否需要
			MODES.halt://待机
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diAzTargetVel := 0;
						bAzCtrlBit8 := TRUE;
					ELSE
						bAzCtrlBit8 := FALSE;
					END_IF
				END_IF

		END_CASE
	END_IF
ELSIF GVL.Error_code<>0 AND GVL.eAzErrorcode = 0 AND NOT GVL.bAzCtrlBit7  AND NOT tr AND NOT bfin1 AND NOT bfin2 THEN
	// 出现错误，轴停止运动
	GVL.diAzTargetVel := 0;
	bAzCtrlBit8 := TRUE;
	TON_0(IN:=bAzCtrlBit8,PT:=T#1S,Q=>,ET=>);//判断stop0执行是否超时,若超时强制下电（手动复位）
	IF TON_0.Q THEN
		bTick:=TRUE;
	END_IF
	IF bTick AND sStatus.Moving THEN // 超时强制下电
		// 写入下电控制字
		GVL.bAzCtrlBit3 := FALSE;
		GVL.bAzCtrlBit0 := FALSE;
		GVL.bAzCtrlBit1 := FALSE;
		GVL.bAzCtrlBit2 := FALSE;
	END_IF
END_IF

