/Device/Plc Logic/Application/RealTimePo:
PROGRAM RealTimePosCal
VAR
	dtReal: DATE_AND_TIME;
	sRealTime:STRING;
	btestTimeInit:BOOL;
	AzCubicInter:threesimple2_1;//方位三次样条插值
	ElCubicInter:threesimple2_1;//俯仰三次样条插值
	iErrcode : INT;
	rInterAzPos:REAL;//方位轴插值位置
    rInterElPos:REAL;//俯仰轴插值位置

	rInterAzPostest:REAL;//方位轴插值位置
    rInterElPostest:REAL;//俯仰轴插值位置

	rPolyAzPos:REAL;//方位轴多项式位置
    rPolyElPos:REAL;//俯仰轴多项式位置
	AzPoly:Get_AZ;
	ElPoly:Get_AZ_1;

	dRTime:ULINT;//上位机外部时间 单位ns Unix时间戳，起点是1970-1-1 0:0:0
	dLastRTime:ULINT;
	icount : INT;
END_VAR

//GVL.dRealTime:= TimeCase.stSYS_Timestamp + GVL.dDelTime + 1000 + 56 ;// 矫正后的时间 单位毫秒
//GVL.dRealTime:= TimeCase.stSYS_Timestamp + GVL.dDelTime;// 矫正后的时间 单位毫秒

//直接从上位机拿数
dRTime := modbus_slave.UTC_New + 8 * 3600 * 1000;
IF dRTime <> dLastRTime THEN
	icount := 0;
ELSE 
	icount := icount + 1;
END_IF
dLastRTime:=dRTime;
IF not GVL.bTimeSwich THEN
	GVL.dRealTime:=GVL.stGNSS_Timestap + 10*timeadd.icount;
ELSE
	GVL.dRealTime:=dRTime + 10*icount;
END_IF
IF icount > 5000 THEN
	icount := 0;
END_IF
(*
GVL.dRealTime:=GVL.stGNSS_Timestap + 10*timeadd.icount;
*)
dtReal := TO_DT(GVL.dRealTime / 1000);
sRealTime := TO_STRING(dtReal);

IF Axis1Remote.iMode=4 AND Axis2Remote.iMode=4 THEN//若PTP时间锁定 且时间模式为PTP时间
		//三次样条插值

		//GVL.dRealTime:= TimeCase.stSYS_Timestamp + GVL.dDelTime + 1000 + 56; // 矫正后的时间 单位毫秒
		IF NOT GVL.bTimeSwich THEN
			GVL.dRealTime:=GVL.stGNSS_Timestap + 10*timeadd.icount;
		ELSE
			GVL.dRealTime:=dRTime + 10*icount;
		END_IF
		AzCubicInter(XModbusUL:=Modbus_Slave.aUTC_TIME,YModbus:=Modbus_Slave.aPosCmd_2,y0:=0,yn:=0,xt:=(ULINT_TO_LREAL(GVL.dRealTime) - 8 * 3600 *1000),sout=>rInterAzPos,ErrCode=>iErrcode);
		ElCubicInter(XModbusUL:=Modbus_Slave.aUTC_TIME,YModbus:=Modbus_Slave.aPosCmd_1,y0:=0,yn:=0,xt:=(ULINT_TO_LREAL(GVL.dRealTime) - 8 * 3600 *1000),sout=>rInterElPos,ErrCode=>iErrcode);
		IF iErrcode>0 THEN //模块内错误代码清0 外部维持
			Error_code:=iErrcode;
		END_IF
END_IF
(*
//IF Axis1Remote.iMode=4 AND Axis2Remote.iMode=4 AND Modbus_Slave.bIFPoly THEN//若PTP时间锁定 且时间模式为PTP时间
IF Modbus_Slave.bIFPoly THEN//若PTP时间锁定 且时间模式为PTP时间
		//多项式拟合

		//GVL.dRealTime:= TimeCase.stSYS_Timestamp + GVL.dDelTime + 1000 + 56; // 矫正后的时间 单位毫秒
		GVL.dRealTime:= GVL.stGNSS_Timestap +450; // 矫正后的时间 单位毫秒

		AzPoly(
		uliRealTime := (ULINT_TO_LREAL(GVL.dRealTime) - 8 * 3600 *1000),
		lrStartTime := Modbus_Slave.starttime,
		rNodeTime1 := Modbus_Slave.rNodeTime1_az,
		rNodeTime2 := Modbus_Slave.rNodeTime2_az,
		rNodeTime3 := Modbus_Slave.rNodeTime3_az,
		rNodeTime4 := Modbus_Slave.rNodeTime4_az,
		rNodeTime5 := Modbus_Slave.rNodeTime5_az,
		rEndTime := Modbus_Slave.rEndTime,
		lrFun1 := Modbus_Slave.lrFun1_az,
		lrFun2 := Modbus_Slave.lrFun2_az,
		lrFun3 := Modbus_Slave.lrFun3_az,
		lrFun4 := Modbus_Slave.lrFun4_az,
		lrFun5 := Modbus_Slave.lrFun5_az,
		lrFun6 := Modbus_Slave.lrFun6_az,
		lrFitResult => rPolyAzPos);

		ElPoly(
		uliRealTime := (ULINT_TO_LREAL(GVL.dRealTime) - 8 * 3600 *1000),
		lrStartTime := Modbus_Slave.starttime,
		rNodeTime1 := Modbus_Slave.rNodeTime1_el,
		rNodeTime2 := Modbus_Slave.rNodeTime2_el,
		rNodeTime3 := Modbus_Slave.rNodeTime3_el,
		rNodeTime4 := Modbus_Slave.rNodeTime4_el,
		rNodeTime5 := Modbus_Slave.rNodeTime5_el,
		rEndTime := Modbus_Slave.rEndTime,
		lrFun1 := Modbus_Slave.lrFun1_el,
		lrFun2 := Modbus_Slave.lrFun2_el,
		lrFun3 := Modbus_Slave.lrFun3_el,
		lrFun4 := Modbus_Slave.lrFun4_el,
		lrFun5 := Modbus_Slave.lrFun5_el,
		lrFun6 := Modbus_Slave.lrFun6_el,
		lrFitResult => rPolyElPos);

		rInterAzPos := rPolyAzPos * (-1);
		rInterElPos := rPolyElPos + 90;
END_IF
*)

/Device/Plc Logic/Application/Az_ctrl_1:
PROGRAM Az_ctrl_1
VAR
    Axis2_Ctrl : Az_Ctrl_FB;
    bRemote2LocalStop : BOOL;
    bLocal2RemoteStop : BOOL;
    Error : INT;
    Axis2Limit_pos : REAL;
    Axis2Limit_Neg : REAL;
    bRTriger : Standard.R_TRIG;
    bFTriger : Standard.F_TRIG;
    Stop2_Count : INT;
    bStop_2 : BOOL;
    rPosModeStepBias : LREAL;
    rPosModeStep : LREAL := 0.005;
    rStepBiasMax : LREAL := 2;
    rStepBias : LREAL;
    rStep : LREAL := 0.002;
    rAuToStepBias : LREAL;
    rAuToStepBiasTemp : LREAL;
    rAutoStep : LREAL := 0.005;
    TbAutoTrigger : Standard.F_TRIG;
    RbAutoTrigger : Standard.R_TRIG;
    rAutoTrackingBiasMax : LREAL := 15;
    rLocalInitPosModeSpeed : REAL;
    rRemoteInitPosModeSpeed : REAL;
    iCountOffAuto : INT;
    iCasePBAutoTrack : INT := 2;
    rKAuToStepBias : LREAL := 0.6; // 对齐2.4
    bVisError : BOOL;
    a : INT;
    agcmaxsearch_tb : agcmaxsearch_pb_1;
    rSearchNextStepTarget_tb : REAL;
    agcmaxsearch_pb : agcmaxsearch_pb_1;
    rElthreshold : REAL := 4.2;
    toN1 : Standard.Ton;
    ttime1 : TIME := T#200mS;
    bstartagcmaxsearch : BOOL;
    rSearchNextStepTarget : REAL;
    rMaxPosTest : REAL;
    iCountSearch : UINT;
    iCountn : UINT;
    bstartSearchAz : BOOL;
    bstartSearchEl : BOOL;
    iCircly : INT := 400;
    rAZSearchThr : REAL := 0.3;
    rElSearchThr : REAL := 0.3;
END_VAR

a := 2;
IF GVL.Error_code <> 0 THEN
	bVisError := TRUE;
ELSE
	bVisError := FALSE;
END_IF
(*
//远控轴参量赋值
Axis2Remote.iMode:=Modbus_Slave.iMode_2;
Axis2Remote.rVelCmd:=Modbus_Slave.rVelcmd_2;
Axis2Remote.rPosCmd:=Modbus_Slave.rPosCmd_2;
Axis2Remote.rP:=Modbus_Slave.rP_2;
Axis2Remote.rI:=Modbus_Slave.rI_2;
Axis2Remote.rD:=Modbus_Slave.rD_2;
Axis2Remote.rPIDThre:=Modbus_Slave.rThreshold_2;
Axis2Remote.rAcceleration:=Modbus_Slave.rAcceleration_2;
Axis2Remote.rDeceleration:=Modbus_Slave.rDeceleration_2;
Axis2Remote.rVel_Limit:=Modbus_Slave.rVelLim_2;
*)
// 方位状态写入
Axis2Status.Error := GVL.bAzStsBit3;
Axis2Status.ErrorID := GVL.eAzErrorcode;
Axis2Status.bServo_Enable := GVL.bAzStsBit0 AND GVL.bAzStsBit1 AND GVL.bAzStsBit2;
Axis2Status.bBrake := NOT (GVL.bAzStsBit0 AND GVL.bAzStsBit1 AND GVL.bAzStsBit2);
Axis2Status.Disabled := NOT (GVL.bAzStsBit0 AND GVL.bAzStsBit1 AND GVL.bAzStsBit2);
Axis2Remote.rSoft_limit_Negative:=-275;Axis2Remote.rSoft_limit_Postive:=275;
Axis2Local.rSoft_limit_Negative:=-275;Axis2Local.rSoft_limit_Postive:=275;

//速度的写入
rFctVelReal_2:=DINT_TO_REAL(diAzActVel)/524288.0*360.0;
//位置的写入，方位0对应编码器0，所以实际方位是：-1*编码器值
rFctPosReal_2:=DINT_TO_REAL(diAzActPos)/524288.0*360.0;

//软限位控制
Axis2Limit_pos:=275;
Axis2Limit_Neg:=-275;
IF Axis2Remote.rPosCmd>Axis2Limit_pos THEN
	Axis2Remote.rPosCmd:=275;
ELSIF Axis2Remote.rPosCmd<Axis2Limit_Neg THEN
	 Axis2Remote.rPosCmd:=-275;  
END_IF

IF Axis2Local.rPosCmd>Axis2Limit_pos THEN
	Axis2Local.rPosCmd:=275;
ELSIF Axis2Local.rPosCmd<Axis2Limit_Neg THEN
	 Axis2Local.rPosCmd:=-275;  
END_IF

//停止标志符号判断
IF  ABS(rFctVelReal_2)<0.035 THEN
	Stop2_Count:=Stop2_Count+1;
	IF Stop2_Count>100 THEN
		Stop2_Count:=101;
		bStop_2:=TRUE;;
	END_IF
ELSE
	Stop2_Count:=0;
	bStop_2:=FALSE;
END_IF
Axis2Status.Moving := NOT bStop_2;
//PID使能赋值
IF Axis2Remote.iMode=2 OR Axis2Remote.iMode=4 THEN
	Axis2Remote.bPIDEnable:=TRUE;
ELSE
	Axis2Remote.bPIDEnable:=FALSE;
END_IF

//本远控逻辑保护
//远控切本控逻辑保护
bRTriger(CLK:=GVL.bLocalCtrl);
bFTriger(CLK:=GVL.bLocalCtrl);

IF Axis2Status.bServo_Enable AND (bRTriger.Q ) THEN//如果速度不为0且本控发生切换，则减速停止标识为True
	bRemote2LocalStop:=TRUE;
END_IF
IF bRemote2LocalStop  THEN //若减速停止标识符为True 

	IF  bStop_2=TRUE THEN//且电机速度不为0 开始减速 减速完成后下使能，下使能完成后复位标识符复位
		Axis2Local.iMode:=0;
		Axis2Remote.iMode:=0;
		IF Axis2Status.bServo_Enable=FALSE THEN
			bRemote2LocalStop:=FALSE;
		END_IF
	ELSE
		Axis2Local.iMode:=7;
		Axis2Remote.iMode:=7;
	END_IF
END_IF

//本控切远控
IF Axis2Status.bServo_Enable AND (bFTriger.Q ) THEN//如果速度不为0且本控发生切换，则减速停止标识为True
	bLocal2RemoteStop:=TRUE;
END_IF
IF bLocal2RemoteStop  THEN //若减速停止标识符为True 

	IF  bStop_2=TRUE THEN//且电机速度不为0 开始减速 减速完成后下使能，下使能完成后复位标识符复位
		Axis2Local.iMode:=0;
		Axis2Remote.iMode:=0;
		IF Axis2Status.bServo_Enable=FALSE THEN
			bLocal2RemoteStop:=FALSE;
		END_IF
	ELSE
		Axis2Remote.iMode:=7;
		Axis2Local.iMode:=7;
	END_IF
END_IF

IF Axis2Remote.iMode=2 THEN
			bstartagcmaxsearch:=Modbus_slave.bSearch;
			IF GVL.Chan1AGC>=(GVL.Chanthreshold-0.1) THEN
					agcmaxsearch_tb(bstart:=bstartagcmaxsearch,rAGCNow:=GVL.Chan1AGC,btrig:=bstartSearchAz,
				rinterPos:=Axis2Remote.rPosCmd,rcurrentpos:=GVL.rFctPosReal_2,
				//rOutStepBias:=0,
				rStepBiasNow:=0,bAutoTracking:=GVL.bStartTrack,bStop:=FALSE,
				rStepBias=>rSearchNextStepTarget_tb,rAGCMaxBias=>rMaxPosTest,bSucess=>);
			ELSE
				bstartagcmaxsearch:=FALSE;
				agcmaxsearch_tb(bstart:=bstartagcmaxsearch,rAGCNow:=GVL.Chan1AGC,btrig:=bstartSearchAz,
				rinterPos:=Axis2Remote.rPosCmd,rcurrentpos:=GVL.rFctPosReal_2,
				//rOutStepBias:=0,
				rStepBiasNow:=0,bAutoTracking:=GVL.bStartTrack,bStop:=FALSE,
				rStepBias=>rSearchNextStepTarget_tb,rAGCMaxBias=>rMaxPosTest,bSucess=>);
			END_IF
			//把rSearchNextStepTarget附加到rPosCmd上
		ELSIF Axis2Remote.iMode=4 AND (GVL.rFctPosReal_1 - 90)>rElthreshold  THEN
			bstartagcmaxsearch:=Modbus_slave.bSearch;
			IF GVL.Chan1AGC>=(GVL.Chanthreshold-0.1) THEN
					agcmaxsearch_pb(bstart:=bstartagcmaxsearch,rAGCNow:=GVL.Chan1AGC,btrig:=bstartSearchAz,
				rinterPos:=RealTimeposcal.rInterAzPos,rcurrentpos:=GVL.rFctPosReal_2,
				//rOutStepBias:=rStepBias,
				rStepBiasNow:=rStepBias,bAutoTracking:=GVL.bStartTrack,bStop:=FALSE,
				rStepBias=>rSearchNextStepTarget,rAGCMaxBias=>rMaxPosTest,bSucess=>);
			ELSE
				bstartagcmaxsearch:=FALSE;
				agcmaxsearch_pb(bstart:=bstartagcmaxsearch,rAGCNow:=GVL.Chan1AGC,btrig:=bstartSearchAz,
				rinterPos:=RealTimeposcal.rInterAzPos,rcurrentpos:=GVL.rFctPosReal_2,
				//rOutStepBias:=rStepBias,
				rStepBiasNow:=rStepBias,bAutoTracking:=GVL.bStartTrack,bStop:=FALSE,
				rStepBias=>rSearchNextStepTarget,rAGCMaxBias=>rMaxPosTest,bSucess=>);
			END_IF
			//把rSearchNextStepTarget附加到Axis2Remote.rPIDCmdPos上
		ELSIF Axis2Remote.iMode =0  OR Axis2Remote.iMode =7 THEN
			bstartagcmaxsearch:=FALSE;
			iCountSearch:=0;
			//rSearchNextStepTarget:=0;
			agcmaxsearch_pb(bstart:=bstartagcmaxsearch,rAGCNow:=GVL.Chan1AGC,btrig:=bstartSearchAz,
			rinterPos:=RealTimeposcal.rInterAzPos,rcurrentpos:=GVL.rFctPosReal_2,
			//rOutStepBias:=rStepBias,
			rStepBiasNow:=rStepBias,bAutoTracking:=GVL.bStartTrack,bStop:=FALSE,
			rStepBias=>rSearchNextStepTarget,rAGCMaxBias=>rMaxPosTest,bSucess=>);
		END_IF

(*
//自跟踪
IF GVL.bStartTrack THEN
	Axis2Remote.bStartAutoTrack := TRUE;
	Axis2Remote.rChanU := -AutoTrackingCal.rChanUa;
ELSE
	Axis2Remote.bStartAutoTrack := FALSE;	
	Axis2Remote.rChanU := 0;
END_IF
*)
// 程引模式下自跟踪拉偏
IF GVL.bStartTrack AND Axis2Remote.iMode=4 THEN
	Axis2Remote.bStartAutoTrack := TRUE;
	IF rAuToStepBias > rAutoTrackingBiasMax THEN
		rAuToStepBias := rAutoTrackingBiasMax;
	ELSIF rAuToStepBias < -rAutoTrackingBiasMax THEN
		rAuToStepBias := -rAutoTrackingBiasMax;
	ELSE
		rAuToStepBiasTemp:=(-0.04)*AutoTrackingCal.rDirSenFac*AutoTrackingCal.rChanUa;
		rAuToStepBias:=rAuToStepBias-AutoTrackingCal.rDirSenFac*rKAuToStepBias*AutoTrackingCal.rChanUa/1000.0;
	END_IF
ELSIF NOT GVL.bStartTrack AND Axis2Remote.iMode=4 THEN
	IF 	rAuToStepBias>0 THEN//关闭自跟踪后自跟踪拉偏量逐渐归0
		rAuToStepBias:=rAuToStepBias-rAutoStep;
	ELSIF rAuToStepBias<0 THEN
		rAuToStepBias:=rAuToStepBias+rAutoStep;
	ELSE
		rAuToStepBias:=0;
	END_IF

	IF Modbus_Slave.rBias_2>rStepBias THEN
		rStepBias:=rStepBias+rStep;
		IF rStepBias>=Modbus_Slave.rBias_2 THEN
			rStepBias:=Modbus_Slave.rBias_2;
		END_IF
	ELSIF Modbus_Slave.rBias_2<rStepBias THEN
		rStepBias:=rStepBias-rStep;
		IF rStepBias<=Modbus_Slave.rBias_2 THEN
			rStepBias:=Modbus_Slave.rBias_2;
		END_IF
	END_IF
	rAuToStepBiasTemp:=0;
ELSIF GVL.bStartTrack AND Axis2Remote.iMode=2 THEN
	Axis2Remote.bStartAutoTrack := TRUE;
	Axis2Remote.rChanU := -AutoTrackingCal.rChanUa;
ELSE
	Axis2Remote.bStartAutoTrack := FALSE;	
	rAuToStepBias:=0;
	rStepBias:=0;
	rAuToStepBiasTemp:=0;
END_IF

//本控自跟踪
IF GVL.bStartLocalAutoTrack AND Axis2Local.iMode = 4 THEN
	Axis2Local.bStartAutoTrack := TRUE;
	Axis2Local.rChanU := -AutoTrackingCal.rChanUaLocal;
ELSE
	Axis2Local.bStartAutoTrack := FALSE;
END_IF
//拉偏
Axis2Remote.rPIDCmdPos:=RealTimePosCal.rInterAzPos+rStepBias+rAuToStepBias+rSearchNextStepTarget-SECURITYCHECK.AZ_out+rAuToStepBiasTemp;

//限位
IF Axis2Remote.rPIDCmdPos<-275 THEN
	Axis2Remote.rPIDCmdPos:=-275;
ELSIF Axis2Remote.rPIDCmdPos>275 THEN
	Axis2Remote.rPIDCmdPos:=275;
END_IF

Axis2_Ctrl(sLocal:=Axis2Local, sCtrl:=Axis2Remote, sStatus:=Axis2Status, sVisible:=Axis2Visible, rRealPos:=rFctPosReal_2, rPosLimK:=0.34);

/Device/Plc Logic/Application/XPTOD_Seri:
////////////////////////////////////////////////////////////////////////////////////////
//串口接收TOD报文解析
//日期：2025/05/15
//版本：V1.1
/////////////////////////////////////////////////////////////////////////////////////////

mPort:=1;                                                                //串口端口号设定，GCAN-PLC-400、GCAN-PLC-510、GCAN-PLC-511，1为232，2为485
                                                                                //GCAN-PLC-324、GCAN-PLC-326，1为第一路485，2为第2路485
IF isFirst THEN
        com_init(                                                        //串口初始化功能块
        EN_IN:=TRUE,                                                //串口初始化功能块使能
        xEnable:=TRUE,                                                //串口功能使能
        bPort:=mPort,                                                //串口端口号设定
        uiBaudrate:=115200,                                        //串口波特率设定
        bParity:=0,                                                        //串口奇偶校验设定，0为无校验，1为奇校验，2为偶检验
        bDatabits:=8,                                                //数据位设定
        bStopbits:=1,                                                //停止位设定
        EN_OUT=>m_out,                                                //串口初始化功能块执行完成标志位
        uiError=>m_uiError);                                //串口初始化功能块执行错误信息
        isfirst:=FALSE;                                                //执行一次初始化后关闭IF的条件使其之后进入ELSE程序段运行

ELSE

                com_read(                                                //串口读取功能块
                EN_in:=TRUE,                                        //读取功能块使能，为TRUE执行读取
                bPort:=mPort,                                        //串口端口号设定
                p_brxdata:=ADR(recBuf),                        //读取到的串口数据引脚为指针类型，使用ADR()指向自建数组将数据存放到数组中
                uiMaxsize:=240,                                        //设定最大读取长度
                EN_out=>m_out,                                        //串口读取功能块执行完成标志位******功能块执行完成不代表接收完成********
                uiRecSize=>recSize,                                //串口接收数据长度，单位：字节，大于0时说明接收到数据可用于判断是否接收
                uierror=>m_uierror);                        //串口读取功能块执行错误信息
                // 查找帧头 $X (36, 88)
                FOR nPos := 1 TO 240 DO
                        IF recBuf[nPos] = 36 AND recBuf[nPos + 1] = 88 THEN
                                nFrameHeadPos := nPos;
                                EXIT;
                        END_IF
                END_FOR
                //解析时间日期 
                IF nFrameHeadPos + 26 <= 240 THEN
                        iYear:=BYTE_TO_INT(recBuf[nFrameHeadPos+23]-48)*1000+BYTE_TO_INT(recBuf[nFrameHeadPos+24]-48)*100+BYTE_TO_INT(recBuf[nFrameHeadPos+25]-48)*10+BYTE_TO_INT(recBuf[26]-48);
                        iMonth:=BYTE_TO_INT(recBuf[nFrameHeadPos+20]-48)*10+BYTE_TO_INT(recBuf[nFrameHeadPos+21]-48);
                        iDay:=BYTE_TO_INT(recBuf[nFrameHeadPos+17]-48)*10+BYTE_TO_INT(recBuf[nFrameHeadPos+18]-48);
                        iHour:=BYTE_TO_INT(recBuf[nFrameHeadPos+7]-48)*10+BYTE_TO_INT(recBuf[nFrameHeadPos+8]-48)+8;
                        iMinute:=BYTE_TO_INT(recBuf[nFrameHeadPos+9]-48)*10+BYTE_TO_INT(recBuf[nFrameHeadPos+10]-48);
                        iSecond:=BYTE_TO_INT(recBuf[nFrameHeadPos+11]-48)*10+BYTE_TO_INT(recBuf[nFrameHeadPos+12]-48);
                        // 计算时间戳                

                        strDateTimeNow := CONCAT(STR1 := 'DT#', STR2 := INT_TO_STRING(iYear));
                        strDateTimeNow := CONCAT(STR1 := strDateTimeNow, STR2 := '-');
                        strDateTimeNow := CONCAT(STR1 := strDateTimeNow, STR2 := INT_TO_STRING(iMonth));
                        strDateTimeNow := CONCAT(STR1 := strDateTimeNow, STR2 := '-');
                        strDateTimeNow := CONCAT(STR1 := strDateTimeNow, STR2 := INT_TO_STRING(iDay));
                        strDateTimeNow := CONCAT(STR1 := strDateTimeNow, STR2 := '-');
                        strDateTimeNow := CONCAT(STR1 := strDateTimeNow, STR2 := INT_TO_STRING(iHour));
                        strDateTimeNow := CONCAT(STR1 := strDateTimeNow, STR2 := ':');
                        strDateTimeNow := CONCAT(STR1 := strDateTimeNow, STR2 := INT_TO_STRING(iMinute));
                        strDateTimeNow := CONCAT(STR1 := strDateTimeNow, STR2 := ':');
                        strDateTimeNow := CONCAT(STR1 := strDateTimeNow, STR2 := INT_TO_STRING(iSecond));

                        gnssTimestamplast:=gnssTimestamp;
                        gnssTimestamp := DT_TO_ULINT(TO_DT(strDateTimeNow)) * 1000;
                        GVL.stGNSS_Timestap := gnssTimestamp;                        
                END_IF

                IF gnssTimestamplast<>gnssTimestamp THEN
                        icount:=0;
                ELSE
                        icount:=icount+1;
                END_IF        
END_IF

