/Device/Plc Logic/Application/Ti_Ctrl_FB:
FUNCTION_BLOCK Ti_Ctrl_FB
VAR_INPUT
	sLocal:AxisCrtlStruct;
	sCtrl:AxisCrtlStruct;
	sStatus:AxisStatus;
	sVisible:AxisVisible;
	rRealPos:REAL;
	rPosLimK:REAL;
END_VAR
VAR_OUTPUT
	logicError:INT;
END_VAR
VAR
	VelPID_1:PID;
	VelPID_2:PID;
	TON_0:TON;
	bTick:BOOL;
	tr:BOOL;
	icount1:INT := 0;
	icount2:INT := 0;
	icount3:INT := 0;
	bfin1:BOOL;
	bfin2:BOOL;
	istate:INT:=0;
	icount:INT:=0;
END_VAR

// 下电时复位控制字bit8
IF sStatus.Disabled OR(NOT sStatus.Moving)THEN
	bTiCtrlBit8 := FALSE;
END_IF

//	错误复位功能
IF GVL.bError_Reset THEN
	sCtrl.iMode:=6;
	sLocal.iMode:=6;
	GVL.Error_code:=0;
END_IF
IF GVL.Error_code =0 THEN
	GVL.bError_Reset:=FALSE;
END_IF

/////////心跳报错清除/////////
IF GVL.eTiErrorcode = 16#8130 AND NOT tr THEN
	GVL.bTiCtrlBit7 := TRUE;
	tr:=TRUE;
	istate:=0;
	icount:=0;
	// 写入下电控制字
	GVL.bTiCtrlBit3 := FALSE;
	GVL.bTiCtrlBit0 := FALSE;
	GVL.bTiCtrlBit1 := FALSE;
	GVL.bTiCtrlBit2 := FALSE;
END_IF
IF tr THEN
	icount1 := icount1 + 1;
END_IF
IF icount1 > 101 THEN
	icount1 := 0;
	tr := FALSE;
	GVL.bTiCtrlBit7 := FALSE;
	bfin1 := TRUE;
END_IF
IF bfin1 THEN
	icount2 := icount2 + 1;
END_IF
IF icount2 > 101 THEN
	bfin1 := FALSE;
	icount2 := 0;
END_IF
/////////////////////////////

IF GVL.Error_code=0 AND GVL.eTiErrorcode = 0 AND NOT GVL.bTiCtrlBit7  AND NOT tr AND NOT bfin1 AND NOT bfin2 THEN
	IF GVL.bLocalCtrl=FALSE THEN //远控
		IF sCtrl.iMode <> 1 THEN
			istate:=0;
			icount:=0;
		END_IF
		CASE sCtrl.iMode OF
			MODES.powerOff: // 下电
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN // 运动中，先停止运动
						GVL.diTiTargetVel := 0;
						bTiCtrlBit8 := TRUE;
					ELSE
						// 写入下电控制字
						GVL.bTiCtrlBit3 := FALSE;
						GVL.bTiCtrlBit0 := FALSE;
						GVL.bTiCtrlBit1 := FALSE;
						GVL.bTiCtrlBit2 := FALSE;
					END_IF
				END_IF
			MODES.powerOn:  // 上电
				IF sStatus.Disabled THEN
					// 目标速度清零
					GVL.diTiTargetVel := 0;
					IF GVL.siTiMode <> 3 THEN // 上电时模式默认为3，速度模式
						GVL.siTiMode := 3;
					END_IF
					IF siTiMode = 3 THEN
						CASE istate OF
							0:
								GVL.bTiCtrlBit1 := TRUE;
								GVL.bTiCtrlBit2 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=1;
								END_IF
							1:
								GVL.bTiCtrlBit0 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=2;
								END_IF
							2:
								GVL.bTiCtrlBit3 := TRUE;
						END_CASE
					END_IF
				ELSE
					IF sStatus.Moving THEN
						GVL.diTiTargetVel := 0;
						bTiCtrlBit8 := TRUE;
					ELSE
						bTiCtrlBit8 := FALSE;
					END_IF
				END_IF
			MODES.positionMode: // 远控指向模式
				IF NOT sStatus.Disabled THEN
					IF sCtrl.bStartAutoTrack THEN
						(*
						//自跟踪模式下，由误差电压直接驱动
						VelPID_1(rTarget:=sCtrl.rChanU + rRealPos,
								rFeedback:=rRealPos,
								rPosLimPositive:=sCtrl.rSoft_limit_Postive,
								rPosLimNegative:=sCtrl.rSoft_limit_Negative,
								rVelLim:=sCtrl.rVel_Limit,
								rKp:=sCtrl.rP_AutoTrack,//自跟踪PI系数3,0.02
								rKi:=sCtrl.rI_AutoTrack,
								rKd:=sCtrl.rD,
								bPIDEnable:=sCtrl.bPIDEnable,
								iThreshold:= -1,
								rPIDOutput=>sCtrl.rPIDCmdVel);
*)							
					ELSE
						//PID计算速度指令
						VelPID_1(rTarget:=sCtrl.rPosCmd,
							rFeedback:=rRealPos,
							rVelLim:=sCtrl.Pos_Vel,
							rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegative:=sCtrl.rSoft_limit_Negative,
							rKp:=0.8,//程引PI系数地带：1,0.002  高带：3,0.02
							rKi:=0,
							rKd:=0,
							bPIDEnable:=sCtrl.bPIDEnable,
							iThreshold:=sCtrl.rPIDThre,
							rPIDOutput=>sCtrl.rPIDCmdVel);
					END_IF
					GVL.diTiTargetVel := REAL_TO_DINT(sCtrl.rPIDCmdVel * 524288 / 360);
					GVL.diTiTargetAcc := REAL_TO_UDINT(10 * 524288 / 360);   //加速度
					GVL.diTiTargetDec := REAL_TO_UDINT(10 * 524288 / 360);   //减速度
				END_IF
			MODES.velocityMode://手控速度模式-远控模式
				IF NOT sStatus.Disabled THEN
					IF ABS(sCtrl.rVelCmd) <= sCtrl.rVel_Limit THEN
						GVL.diTiTargetVel := REAL_TO_DINT(sCtrl.rVelCmd * 524288 / 360);
					ELSIF sCtrl.rVelCmd > sCtrl.rVel_Limit THEN
						GVL.diTiTargetVel := REAL_TO_DINT(sCtrl.rVel_Limit * 524288 / 360);
					ELSE
						GVL.diTiTargetVel := REAL_TO_DINT(-sCtrl.rVel_Limit * 524288 / 360);
					END_IF
					GVL.diTiTargetAcc := REAL_TO_UDINT(sCtrl.rAcceleration * 524288 / 360);   //加速度
					GVL.diTiTargetDec := REAL_TO_UDINT(sCtrl.rDeceleration * 524288 / 360);   //减速度
				END_IF
			MODES.programBootMode://PID速度模式-正常模式 程引
				IF NOT sStatus.Disabled THEN
					IF sCtrl.bStartAutoTrack THEN
						//自跟踪模式下，由误差电压直接驱动
						VelPID_1(rTarget:=sCtrl.rChanU + rRealPos,
								rFeedback:=rRealPos,
								rPosLimPositive:=sCtrl.rSoft_limit_Postive,
								rPosLimNegative:=sCtrl.rSoft_limit_Negative,
								rVelLim:=sCtrl.rVel_Limit,
								rKp:=sCtrl.rP_AutoTrack,//自跟踪PI系数3,0.02
								rKi:=sCtrl.rI_AutoTrack,
								rKd:=sCtrl.rD,
								bPIDEnable:=sCtrl.bPIDEnable,
								iThreshold:= -1,
								rPIDOutput=>sCtrl.rPIDCmdVel);							
					ELSE
						//PID计算速度指令
						VelPID_1(rTarget:=sCtrl.rPIDCmdPos,
							rFeedback:=rRealPos,
							rVelLim:=sCtrl.rVel_Limit,
							rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegative:=sCtrl.rSoft_limit_Negative,
							rKp:=sCtrl.rP,//程引PI系数地带：1,0.002  高带：3,0.02
							rKi:=sCtrl.rI,
							rKd:=sCtrl.rD,
							bPIDEnable:=sCtrl.bPIDEnable,
							iThreshold:=sCtrl.rPIDThre,
							rPIDOutput=>sCtrl.rPIDCmdVel);
					END_IF
					GVL.diTiTargetVel := REAL_TO_DINT(sCtrl.rPIDCmdVel * 524288 / 360);
					GVL.diTiTargetAcc := REAL_TO_UDINT(sCtrl.rAcceleration * 524288 / 360);   //加速度
					GVL.diTiTargetDec := REAL_TO_UDINT(sCtrl.rDeceleration * 524288 / 360);   //减速度
				END_IF
			MODES.reset://重置
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diTiTargetVel := 0;
						bTiCtrlBit8 := TRUE;
					ELSE
						bTiCtrlBit8 := FALSE;
					END_IF
				END_IF
			MODES.halt://待机
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diTiTargetVel := 0;
						bTiCtrlBit8 := TRUE;
					ELSE
						bTiCtrlBit8 := FALSE;
					END_IF
				END_IF

		END_CASE
	ELSE // 本控
		IF sLocal.iMode <> 1 THEN
			istate:=0;
			icount:=0;
		END_IF
		CASE sLocal.iMode OF
			MODES.powerOff: // 下电
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN // 运动中，先停止运动
						GVL.diTiTargetVel := 0;
						bTiCtrlBit8 := TRUE;
					ELSE
						// 写入下电控制字
						GVL.bTiCtrlBit3 := FALSE;
						GVL.bTiCtrlBit0 := FALSE;
						GVL.bTiCtrlBit1 := FALSE;
						GVL.bTiCtrlBit2 := FALSE;
					END_IF
				END_IF
			MODES.powerOn:  // 上电
				IF sStatus.Disabled THEN
					// 目标速度清零
					GVL.diTiTargetVel := 0;
					IF GVL.siTiMode <> 3 THEN // 上电时模式默认为3，速度模式
						GVL.siTiMode := 3;
					END_IF
					IF siTiMode = 3 THEN
						CASE istate OF
							0:
								GVL.bTiCtrlBit1 := TRUE;
								GVL.bTiCtrlBit2 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=1;
								END_IF
							1:
								GVL.bTiCtrlBit0 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=2;
								END_IF
							2:
								GVL.bTiCtrlBit3 := TRUE;
						END_CASE
					END_IF
				ELSE
					IF sStatus.Moving THEN
						GVL.diTiTargetVel := 0;
						bTiCtrlBit8 := TRUE;
					ELSE
						bTiCtrlBit8 := FALSE;
					END_IF
				END_IF
			MODES.velocityMode://手控速度模式-本控模式
				IF NOT sStatus.Disabled THEN
					IF ABS(sLocal.rVelCmd) <= sLocal.rVel_Limit THEN
						GVL.diTiTargetVel := REAL_TO_DINT(sLocal.rVelCmd * 524288 / 360);
					ELSIF sLocal.rVelCmd > sLocal.rVel_Limit THEN
						GVL.diTiTargetVel := REAL_TO_DINT(sLocal.rVel_Limit * 524288 / 360);
					ELSE
						GVL.diTiTargetVel := REAL_TO_DINT(-sLocal.rVel_Limit * 524288 / 360);
					END_IF
					GVL.diTiTargetAcc := REAL_TO_UDINT(sLocal.rAcceleration * 524288 / 360);   //加速度
					GVL.diTiTargetDec := REAL_TO_UDINT(sLocal.rDeceleration * 524288 / 360);   //减速度
				END_IF
			MODES.programBootMode://本控位置模式
				IF NOT sStatus.Disabled THEN
					IF NOT sLocal.bPIDEnable THEN
						GVL.diTiTargetVel := 0;							
					ELSE
						//PID计算速度指令
						 VelPID_2(rTarget:=sLocal.rPosCmd,
							     rFeedback:=rRealPos,
								 rPosLimPositive:=sLocal.rSoft_limit_Postive,//软限位
								 rPosLimNegative:=sLocal.rSoft_limit_Negative,
								 rKp:=sLocal.rP,
								 rKi:=sLocal.rI,
								 rKd:=sLocal.rD,
								 iThreshold:=sLocal.rPIDThre,
								 bPIDEnable:=sLocal.bPIDEnable,
								 rVelLim:=sLocal.Pos_Vel,
								 rPIDOutput=>sLocal.rPIDCmdVel);//普通PID
					END_IF
					GVL.diTiTargetVel := REAL_TO_DINT(sLocal.rPIDCmdVel * 524288 / 360);
					GVL.diTiTargetAcc := REAL_TO_UDINT(sLocal.rAcceleration * 524288 / 360);   //加速度
					GVL.diTiTargetDec := REAL_TO_UDINT(sLocal.rDeceleration * 524288 / 360);   //减速度
				END_IF
			MODES.reset://重置
			// 是否需要
			MODES.halt://待机
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diTiTargetVel := 0;
						bTiCtrlBit8 := TRUE;
					ELSE
						bTiCtrlBit8 := FALSE;
					END_IF
				END_IF

		END_CASE
	END_IF
ELSIF GVL.Error_code<>0 AND GVL.eTiErrorcode = 0 AND NOT GVL.bTiCtrlBit7  AND NOT tr AND NOT bfin1 AND NOT bfin2 THEN
	// 出现错误，轴停止运动
	GVL.diTiTargetVel := 0;
	bTiCtrlBit8 := TRUE;
	TON_0(IN:=bTiCtrlBit8,PT:=T#1S,Q=>,ET=>);//判断stop0执行是否超时,若超时强制下电（手动复位）
	IF TON_0.Q THEN
		bTick:=TRUE;
	END_IF
	IF bTick AND sStatus.Moving THEN // 超时强制下电
		// 写入下电控制字
		GVL.bTiCtrlBit3 := FALSE;
		GVL.bTiCtrlBit0 := FALSE;
		GVL.bTiCtrlBit1 := FALSE;
		GVL.bTiCtrlBit2 := FALSE;
	END_IF
END_IF

/Device/Plc Logic/Application/El_ctrl_1:
PROGRAM El_ctrl_1
VAR
    Axis1_Ctrl : El_Ctrl_FB;
    bRemote2LocalStop : BOOL;
    bLocal2RemoteStop : BOOL;
    Error : INT;
    Axis1Limit_pos : REAL;
    Axis1Limit_Neg : REAL;
    bRTriger : Standard.R_TRIG;
    bFTriger : Standard.F_TRIG;
    Stop1_Count : INT;
    bStop_1 : BOOL;
    rPosModeStepBias : LREAL;
    rPosModeStep : LREAL := 0.005;
    rStepBiasMax : LREAL := 2;
    rStepBias : LREAL;
    rStep : LREAL := 0.002;
    rAuToStepBias : LREAL;
    rAuToStepBiasTemp : LREAL;
    rAutoStep : LREAL := 0.01;
    TbAutoTrigger : Standard.F_TRIG;
    RbAutoTrigger : Standard.R_TRIG;
    rAutoTrackingBiasMax : LREAL := 6;
    rLocalInitPosModeSpeed : REAL;
    rRemoteInitPosModeSpeed : REAL;
    iCountOffAuto : INT;
    iCasePBAutoTrack : INT := 2;
    rKAuToStepBias : LREAL := 0.45; // 对齐2.4
    agcmaxsearch_tb : AGCMaxSearch_PB_1;
    rSearchNextStepTarget_tb : REAL;
    agcmaxsearch_pb : AGCMaxSearch_PB_1;
    rElthreshold : REAL := 4.2;
    toN1 : Standard.Ton;
    ttime1 : TIME := T#200mS;
    bstartagcmaxsearch : BOOL;
    rSearchNextStepTarget : REAL;
    rMaxPosTest : REAL;
END_VAR

(*
//远控轴参量赋值
Axis1Remote.iMode:=Modbus_Slave.iMode_1;
Axis1Remote.rVelCmd:=Modbus_Slave.rVelcmd_1;
Axis1Remote.rPosCmd:=Modbus_Slave.rPosCmd_1;
Axis1Remote.rP:=Modbus_Slave.rP_1;
Axis1Remote.rI:=Modbus_Slave.rI_1;
Axis1Remote.rD:=Modbus_Slave.rD_1;
Axis1Remote.rPIDThre:=Modbus_Slave.rThreshold_1;
Axis1Remote.rAcceleration:=Modbus_Slave.rAcceleration_1;
Axis1Remote.rDeceleration:=Modbus_Slave.rDeceleration_1;
Axis1Remote.rVel_Limit:=Modbus_Slave.rVelLim_1;
*)
// 方位状态写入
Axis1Status.Error := GVL.bElStsBit3;
Axis1Status.ErrorID := GVL.eElErrorcode;
Axis1Status.bServo_Enable := GVL.bElStsBit0 AND GVL.bElStsBit1 AND GVL.bElStsBit2;
Axis1Status.bBrake := NOT (GVL.bElStsBit0 AND GVL.bElStsBit1 AND GVL.bElStsBit2);
Axis1Status.Disabled := NOT (GVL.bElStsBit0 AND GVL.bElStsBit1 AND GVL.bElStsBit2);
Axis1Remote.rSoft_limit_Negative:=93;Axis1Remote.rSoft_limit_Postive:=180;
Axis1Local.rSoft_limit_Negative:=93;Axis1Local.rSoft_limit_Postive:=180;

//速度的写入
rFctVelReal_1:=DINT_TO_REAL(diElActVel)/524288.0*360.0;
//位置的写入，方位0对应编码器0，所以实际方位是：-1*编码器值
//rFctPosReal_1:=DINT_TO_REAL(diElActPos)/524288.0*360.0 + 5.339;
rFctPosReal_1:=DINT_TO_REAL(diElActPos)/524288.0*360.0 + modbus_slave.lrElOffset;
//软限位控制
Axis1Limit_pos:=180;
Axis1Limit_Neg:=93;
IF Axis1Remote.rPosCmd>Axis1Limit_pos THEN
	Axis1Remote.rPosCmd:=180;
ELSIF Axis1Remote.rPosCmd<Axis1Limit_Neg THEN
	 Axis1Remote.rPosCmd:=93;  
END_IF

IF Axis1Local.rPosCmd>Axis1Limit_pos THEN
	Axis1Local.rPosCmd:=180;
ELSIF Axis1Local.rPosCmd<Axis1Limit_Neg THEN
	 Axis1Local.rPosCmd:=93;  
END_IF

//停止标志符号判断
IF  ABS(rFctVelReal_1)<0.035 THEN
	Stop1_Count:=Stop1_Count+1;
	IF Stop1_Count>100 THEN
		Stop1_Count:=101;
		bStop_1:=TRUE;;
	END_IF
ELSE
	Stop1_Count:=0;
	bStop_1:=FALSE;
END_IF
Axis1Status.Moving := NOT bStop_1;
//PID使能赋值
IF Axis1Remote.iMode=2 OR Axis1Remote.iMode=4 THEN
	Axis1Remote.bPIDEnable:=TRUE;
ELSE
	Axis1Remote.bPIDEnable:=FALSE;
END_IF

//本远控逻辑保护
//远控切本控逻辑保护
bRTriger(CLK:=GVL.bLocalCtrl);
bFTriger(CLK:=GVL.bLocalCtrl);

IF Axis1Status.bServo_Enable AND (bRTriger.Q ) THEN//如果速度不为0且本控发生切换，则减速停止标识为True
	bRemote2LocalStop:=TRUE;
END_IF
IF bRemote2LocalStop  THEN //若减速停止标识符为True 

	IF  bStop_1=TRUE THEN//且电机速度不为0 开始减速 减速完成后下使能，下使能完成后复位标识符复位
		Axis1Local.iMode:=0;
		Axis1Remote.iMode:=0;
		IF Axis1Status.bServo_Enable=FALSE THEN
			bRemote2LocalStop:=FALSE;
		END_IF
	ELSE
		Axis1Local.iMode:=7;
		Axis1Remote.iMode:=7;
	END_IF
END_IF

//本控切远控
IF Axis1Status.bServo_Enable AND (bFTriger.Q ) THEN//如果速度不为0且本控发生切换，则减速停止标识为True
	bLocal2RemoteStop:=TRUE;
END_IF
IF bLocal2RemoteStop  THEN //若减速停止标识符为True 

	IF  bStop_1=TRUE THEN//且电机速度不为0 开始减速 减速完成后下使能，下使能完成后复位标识符复位
		Axis1Local.iMode:=0;
		Axis1Remote.iMode:=0;
		IF Axis1Status.bServo_Enable=FALSE THEN
			bLocal2RemoteStop:=FALSE;
		END_IF
	ELSE
		Axis1Remote.iMode:=7;
		Axis1Local.iMode:=7;
	END_IF
END_IF
(*
//自跟踪
IF GVL.bStartTrack THEN
	Axis1Remote.bStartAutoTrack := TRUE;
	Axis1Remote.rChanU := AutoTrackingCal.rChanUe;
ELSE
	Axis1Remote.bStartAutoTrack := FALSE;	
	Axis1Remote.rChanU := 0;
END_IF
*)
IF Axis1Remote.iMode=2 THEN
			IF GVL.Chan1AGC>=(GVL.Chanthreshold-0.1) THEN
					agcmaxsearch_pb(bstart:=Az_ctrl_1.agcmaxsearch_tb.bSucess,rAGCNow:=GVL.Chan1AGC,btrig:=Az_ctrl_1.bstartSearchEl,
						rCurrentPos:=rFctPosReal_1,rInterPos:=Axis1Remote.rPosCmd,
				//rOutStepBias:=rStepBias,	
				rStepBiasNow:=rStepBias,bAutoTracking:=GVL.bStartTrack,bStop:=FALSE,
				rStepBias=>rSearchNextStepTarget_tb,rAGCMaxBias=>rMaxPosTest,bSucess=>);
			ELSE
				bstartagcmaxsearch:=FALSE;
				agcmaxsearch_pb(bstart:=Az_ctrl_1.agcmaxsearch_tb.bSucess,rAGCNow:=GVL.Chan1AGC,btrig:=Az_ctrl_1.bstartSearchEl,
				rCurrentPos:=rFctPosReal_1,rInterPos:=Axis1Remote.rPosCmd,
				//rOutStepBias:=rStepBias,
				rStepBiasNow:=rStepBias,bAutoTracking:=GVL.bStartTrack,bStop:=FALSE,
				rStepBias=>rSearchNextStepTarget_tb,rAGCMaxBias=>rMaxPosTest,bSucess=>);
			END_IF
		ELSIF Axis1Remote.iMode=4 AND rFctPosReal_1-90>rElthreshold  THEN
			IF GVL.Chan1AGC>=(GVL.Chanthreshold-0.1) THEN
					agcmaxsearch_pb(bstart:=Az_ctrl_1.agcmaxsearch_pb.bSucess,rAGCNow:=GVL.Chan1AGC,btrig:=Az_ctrl_1.bstartSearchEl,
						rCurrentPos:=rFctPosReal_1,rInterPos:=RealTimePosCal.rInterElPos,
				//rOutStepBias:=rStepBias,	
				rStepBiasNow:=rStepBias,bAutoTracking:=GVL.bStartTrack,bStop:=FALSE,
				rStepBias=>rSearchNextStepTarget,rAGCMaxBias=>rMaxPosTest,bSucess=>);
			ELSE
				bstartagcmaxsearch:=FALSE;
				agcmaxsearch_pb(bstart:=Az_ctrl_1.agcmaxsearch_pb.bSucess,rAGCNow:=GVL.Chan1AGC,btrig:=Az_ctrl_1.bstartSearchEl,
				rCurrentPos:=rFctPosReal_1,rInterPos:=RealTimePosCal.rInterElPos,
				//rOutStepBias:=rStepBias,
				rStepBiasNow:=rStepBias,bAutoTracking:=GVL.bStartTrack,bStop:=FALSE,
				rStepBias=>rSearchNextStepTarget,rAGCMaxBias=>rMaxPosTest,bSucess=>);
			END_IF
			//把rSearchNextStepTarget附加到AzCtrl.rPIDCmdPos上
		ELSIF Axis1Remote.iMode =0  OR Axis1Remote.iMode =7 THEN
			bstartagcmaxsearch:=FALSE;
			//rSearchNextStepTarget:=0;
			agcmaxsearch_pb(bstart:=Az_ctrl_1.agcmaxsearch_pb.bSucess,rAGCNow:=GVL.Chan1AGC,btrig:=Az_ctrl_1.bstartSearchEl,
			rCurrentPos:=rFctPosReal_1,rInterPos:=RealTimePosCal.rInterElPos,	
			//rOutStepBias:=rStepBias,
			rStepBiasNow:=rStepBias,bAutoTracking:=GVL.bStartTrack,bStop:=FALSE,
			rStepBias=>rSearchNextStepTarget,rAGCMaxBias=>rMaxPosTest,bSucess=>);
		END_IF
// 程引模式下自跟踪拉偏
IF GVL.bStartTrack AND Axis1Remote.iMode=4 THEN
	Axis1Remote.bStartAutoTrack := TRUE;
	IF rAuToStepBias > rAutoTrackingBiasMax THEN
		rAuToStepBias := rAutoTrackingBiasMax;
	ELSIF rAuToStepBias < -rAutoTrackingBiasMax THEN
		rAuToStepBias := -rAutoTrackingBiasMax;
	ELSE
		rAuToStepBiasTemp:=0.02*AutoTrackingCal.rDirSenFac*AutoTrackingCal.rChanUe;
		rAuToStepBias:=rAuToStepBias+AutoTrackingCal.rDirSenFac*rKAuToStepBias*AutoTrackingCal.rChanUe/1000.0;
	END_IF
ELSIF NOT GVL.bStartTrack AND Axis1Remote.iMode=4 THEN
	IF 	rAuToStepBias>0 THEN//关闭自跟踪后自跟踪拉偏量逐渐归0
		rAuToStepBias:=rAuToStepBias-rAutoStep;
	ELSIF rAuToStepBias<0 THEN
		rAuToStepBias:=rAuToStepBias+rAutoStep;
	ELSE
		rAuToStepBias:=0;
	END_IF

	IF Modbus_Slave.rBias_1>rStepBias THEN
		rStepBias:=rStepBias+rStep;
		IF rStepBias>=Modbus_Slave.rBias_1 THEN
			rStepBias:=Modbus_Slave.rBias_1;
		END_IF
	ELSIF Modbus_Slave.rBias_1<rStepBias THEN
		rStepBias:=rStepBias-rStep;
		IF rStepBias<=Modbus_Slave.rBias_1 THEN
			rStepBias:=Modbus_Slave.rBias_1;
		END_IF
	END_IF
	rAuToStepBiasTemp:=0;
ELSIF GVL.bStartTrack AND Axis1Remote.iMode=2 THEN
	Axis1Remote.bStartAutoTrack := TRUE;
	Axis1Remote.rChanU := AutoTrackingCal.rChanUe;
ELSE
	Axis1Remote.bStartAutoTrack := FALSE;	
	rAuToStepBias:=0;
	rStepBias:=0;
	rAuToStepBiasTemp:=0;
END_IF

//本控自跟踪
IF GVL.bStartLocalAutoTrack AND Axis1Local.iMode = 4 THEN
	Axis1Local.bStartAutoTrack := TRUE;
	Axis1Local.rChanU := AutoTrackingCal.rChanUeLocal;
ELSE
	Axis1Local.bStartAutoTrack := FALSE;
END_IF

//拉偏
Axis1Remote.rPIDCmdPos:=RealTimePosCal.rInterElPos+rStepBias+rAuToStepBias+rSearchNextStepTarget+SECURITYCHECK.el_out+rAuToStepBiasTemp;
//限位
IF Axis1Remote.rPIDCmdPos<93 THEN
	Axis1Remote.rPIDCmdPos:=93;
ELSIF Axis1Remote.rPIDCmdPos>180 THEN
	Axis1Remote.rPIDCmdPos:=180;
END_IF

Axis1_Ctrl(sLocal:=Axis1Local, sCtrl:=Axis1Remote, sStatus:=Axis1Status, sVisible:=Axis1Visible, rRealPos:=rFctPosReal_1, rPosLimK:=0.34);

