/Device/Plc Logic/Application/Get_AZ_1:
FUNCTION_BLOCK Get_AZ_1
VAR_INPUT
	uliRealTime : LREAL; // 当前时间戳，单位毫秒
	lrStartTime : LREAL; // 任务起始时间，单位秒
	rNodeTime1 : REAL;
	rNodeTime2 : REAL;
	rNodeTime3 : REAL;
    rNodeTime4 : REAL;
    rNodeTime5 : REAL;
	rEndTime : REAL;
	lrFun1 : ARRAY[0..10] OF LREAL;
	lrFun2 : ARRAY[0..10] OF LREAL;
	lrFun3 : ARRAY[0..10] OF LREAL;
	lrFun4 : ARRAY[0..10] OF LREAL;
	lrFun5 : ARRAY[0..10] OF LREAL;
	lrFun6 : ARRAY[0..10] OF LREAL;
END_VAR
VAR_OUTPUT
	lrFitResult : LREAL;
END_VAR
VAR
	rDelTime : REAL;
	rRealTime : LREAL;
END_VAR

rRealTime := uliRealTime / 1000.0 - lrStartTime/1000.0;


IF rRealTime <= 0.0 THEN
	rDelTime := 0.0;
	lrFitResult := lrFun1[10];
ELSIF rRealTime <= rNodeTime1 THEN
    rDelTime := rRealTime - 0.0;
	lrFitResult := lrFun1[0] * EXPT(rDelTime,10) + lrFun1[1] * EXPT(rDelTime,9) + lrFun1[2] * EXPT(rDelTime,8) + lrFun1[3] * EXPT(rDelTime,7) + lrFun1[4] * EXPT(rDelTime,6) + lrFun1[5] * EXPT(rDelTime,5)
    + lrFun1[6] * EXPT(rDelTime,4) + lrFun1[7] * EXPT(rDelTime,3) + lrFun1[8] * EXPT(rDelTime,2) + lrFun1[9] * rDelTime + lrFun1[10];
ELSIF rRealTime <= rNodeTime2 THEN
    rDelTime := rRealTime - rNodeTime1;
    lrFitResult := lrFun2[0] * EXPT(rDelTime,10) + lrFun2[1] * EXPT(rDelTime,9) + lrFun2[2] * EXPT(rDelTime,8) + lrFun2[3] * EXPT(rDelTime,7) + lrFun2[4] * EXPT(rDelTime,6) + lrFun2[5] * EXPT(rDelTime,5)
    + lrFun2[6] * EXPT(rDelTime,4) + lrFun2[7] * EXPT(rDelTime,3) + lrFun2[8] * EXPT(rDelTime,2) + lrFun2[9] * rDelTime + lrFun2[10];
ELSIF rRealTime <= rNodeTime3 THEN
    rDelTime := rRealTime - rNodeTime2;
    lrFitResult := lrFun3[0] * EXPT(rDelTime,10) + lrFun3[1] * EXPT(rDelTime,9) + lrFun3[2] * EXPT(rDelTime,8) + lrFun3[3] * EXPT(rDelTime,7) + lrFun3[4] * EXPT(rDelTime,6) + lrFun3[5] * EXPT(rDelTime,5)
    + lrFun3[6] * EXPT(rDelTime,4) + lrFun3[7] * EXPT(rDelTime,3) + lrFun3[8] * EXPT(rDelTime,2) + lrFun3[9] * rDelTime + lrFun3[10];
ELSIF rRealTime <= rNodeTime4 THEN
    rDelTime := rRealTime - rNodeTime3;
    lrFitResult := lrFun4[0] * EXPT(rDelTime,10) + lrFun4[1] * EXPT(rDelTime,9) + lrFun4[2] * EXPT(rDelTime,8) + lrFun4[3] * EXPT(rDelTime,7) + lrFun4[4] * EXPT(rDelTime,6) + lrFun4[5] * EXPT(rDelTime,5)
    + lrFun4[6] * EXPT(rDelTime,4) + lrFun4[7] * EXPT(rDelTime,3) + lrFun4[8] * EXPT(rDelTime,2) + lrFun4[9] * rDelTime + lrFun4[10];
ELSIF rRealTime <= rNodeTime5 THEN
    rDelTime := rRealTime - rNodeTime4;
    lrFitResult := lrFun5[0] * EXPT(rDelTime,10) + lrFun5[1] * EXPT(rDelTime,9) + lrFun5[2] * EXPT(rDelTime,8) + lrFun5[3] * EXPT(rDelTime,7) + lrFun5[4] * EXPT(rDelTime,6) + lrFun5[5] * EXPT(rDelTime,5)
    + lrFun5[6] * EXPT(rDelTime,4) + lrFun5[7] * EXPT(rDelTime,3) + lrFun5[8] * EXPT(rDelTime,2) + lrFun5[9] * rDelTime + lrFun5[10];
ELSIF rRealTime <= rEndTime THEN
    rDelTime := rRealTime - rNodeTime5;
    lrFitResult := lrFun6[0] * EXPT(rDelTime,10) + lrFun6[1] * EXPT(rDelTime,9) + lrFun6[2] * EXPT(rDelTime,8) + lrFun6[3] * EXPT(rDelTime,7) + lrFun6[4] * EXPT(rDelTime,6) + lrFun6[5] * EXPT(rDelTime,5)
    + lrFun6[6] * EXPT(rDelTime,4) + lrFun6[7] * EXPT(rDelTime,3) + lrFun6[8] * EXPT(rDelTime,2) + lrFun6[9] * rDelTime + lrFun6[10];
ELSE
    rDelTime := rEndTime - rNodeTime5;
    lrFitResult := lrFun6[0] * EXPT(rDelTime,10) + lrFun6[1] * EXPT(rDelTime,9) + lrFun6[2] * EXPT(rDelTime,8) + lrFun6[3] * EXPT(rDelTime,7) + lrFun6[4] * EXPT(rDelTime,6) + lrFun6[5] * EXPT(rDelTime,5)
    + lrFun6[6] * EXPT(rDelTime,4) + lrFun6[7] * EXPT(rDelTime,3) + lrFun6[8] * EXPT(rDelTime,2) + lrFun6[9] * rDelTime + lrFun6[10];
END_IF

IF lrFitResult>90 THEN
	lrFitResult:=90;
ELSIF lrFitResult<3 THEN
	lrFitResult:=3;
END_IF

/Device/Plc Logic/Application/vpid:
FUNCTION_BLOCK vpid
VAR_INPUT
	rTarget : REAL;           // 设定值
    rFeedback : REAL;         // 反馈值
    rPosLimPositive : LREAL;  // 位置正限位
    rPosLimNegitive : LREAL;  // 位置反限位
    rKpBase : REAL;           // 基础比例增益
    rKiBase : REAL;           // 基础积分增益
    rVelThreshold : LREAL;     // 速度阈值，真实值除以控制频率
    rKpScale : REAL;          // 比例增益比例因子
    rKiScale : REAL;          // 积分增益比例因子
    iThrehold : INT;          // 积分项开启的位置阈值
    bPIDEnable : BOOL := TRUE;// PID使能
    rVelLim : LREAL;          // 速度限制
	rKpMax : REAL;
	rKiMax : REAL;
	rElPos : REAL;            // 俯仰角度
END_VAR

VAR_OUTPUT
    rPIDOutput : LREAL := 0;  // 控制量
	rPIDOutDir: LREAL;
END_VAR

VAR
    rLastFeedback : LREAL := 0.0; // 上一次反馈值
    rErrorNow : LREAL := 0.0;     // 当前误差
    rIntegralNew : LREAL := 0.0;  // 积分项
    rDelta : LREAL;               // 增量
    rProportionNew : LREAL;       // 比例项
    rSpeed : REAL;                // 当前速度
    rKp : REAL:=1;                   // 动态比例增益
    rKi : REAL:=0.02;                   // 动态积分增益
	rInterValueNow : LREAL := 0.0;        // 当前插值位置
	rInterValueLast : LREAL := 0.0;       // 上一次插值位置
	//rSlope :LREAL :=0; 			  //PI变化斜率
	rStep:LREAL:=0.002;                //PI变化率

	rKpTarget :REAL:=1;
	rKiTarget :REAL:=0.02;


END_VAR
IF (bPIDEnable) THEN // 如果PID使能
    IF rTarget = rFeedback THEN
        rPIDOutDir := 0;    
    ELSE
        rErrorNow := rTarget - rFeedback; // 计算当前误差
        rProportionNew := rErrorNow;      // 比例项

		IF rElPos > rVelThreshold THEN
			rKpTarget := rKpBase + rKpScale * (rElPos - rVelThreshold);
			rKiTarget := rKiBase + rKiScale * (rElPos - rVelThreshold);
		ELSE
			rKpTarget := rKpBase;
			rKiTarget := rKiBase;
		END_IF
//         rInterValueLast := rInterValueNow; // 将当前插值位置值赋值给上一次
// 		rInterValueNow := RealTimePosCal.ElCubicInter.sout*10000.0;
//         // 计算当前速度
//         // rSpeed := ABS(rFeedback - rLastFeedback);
//         rSpeed := ABS(rInterValueNow - rInterValueLast)/10000.0;
// 		
//         // 根据速度调整PI增益
//         IF rSpeed > rVelThreshold THEN
//             rKpTarget := rKpBase + rKpScale * (rSpeed - rVelThreshold);
//             rKiTarget := rKiBase + rKiScale * (rSpeed - rVelThreshold);
//         ELSE
//             rKpTarget := rKpBase;
//             rKiTarget := rKiBase;
//         END_IF
        IF rKpTarget > rKpMax THEN
			rKpTarget := rKpMax;
		END_IF
		IF rKiTarget > rKiMax THEN
			rKiTarget := rKiMax;
		END_IF

		IF rKp<=rKpTarget THEN
			rKp:=rKp+rStep;
		ELSE
			rKp:=rKp-rStep;
		END_IF
		IF rKi<=rKiTarget THEN
			rKi:=rKi+(rKiScale/rKpScale)*rStep;
		ELSE
			rKi:=rKi-(rKiScale/rKpScale)*rStep;
		END_IF
	END_IF
        // 积分项
        IF rFeedback > rPosLimNegitive AND rFeedback < rPosLimPositive THEN // 若在软限位之内，工作时开启积分项
            IF (ABS(rTarget - rFeedback) < iThrehold) THEN // 位置差小于积分阈值
                rIntegralNew := rIntegralNew + rErrorNow;  // 积分项
            ELSE
                rIntegralNew := rIntegralNew;  // 积分项
            END_IF;
        ELSE // 不在软限位范围内，则积分项为0
            rIntegralNew := 0;
        END_IF
        (*
        // 防止目标位置与当前位置偏差过大，导致比例项输出太大，引起震动
        IF rKp * rProportionNew > 2 THEN
            rPIDOutput := 2;
        ELSIF rKp * rProportionNew < -2 THEN
            rPIDOutput := -2;
        ELSE
            rPIDOutput := rKp * rProportionNew + rKi * rIntegralNew / 1000.0; // 由于需求积分项过小，因此积分系数在接口数据上除1000
        END_IF
        *)
		rPIDOutput := rKp * rProportionNew + rKi * rIntegralNew; // 由于需求积分项过小，因此积分系数在接口数据上除1000
        // 根据方向设置输出
        IF rPIDOutput < 0 THEN

            rPIDOutDir := rPIDOutput;
        ELSE

            rPIDOutDir := rPIDOutput;
        END_IF

        // PID限速
        IF (ABS(rPIDOutDir) > rVelLim) THEN
            IF rPIDOutDir < (-rVelLim) THEN
                rPIDOutDir := -rVelLim;
            ELSIF rPIDOutDir > rVelLim THEN
                rPIDOutDir := rVelLim;
            END_IF
        END_IF

        // 位置限位检查
        IF rFeedback > rPosLimPositive AND rPIDOutDir > 0  THEN
            rPIDOutDir := 0;
        END_IF
        IF rFeedback < rPosLimNegitive AND rPIDOutDir <= 0 THEN
            rPIDOutDir := 0;
        END_IF

        //rLastFeedback := rFeedback; // 将当前反馈值赋值给上一次反馈值
		//rInterValueLast := rInterValueNow; // 将当前插值位置值赋值给上一次

ELSE // 非使能清零PID各项
    rProportionNew := 0.0;
    rIntegralNew := 0.0;
    rPIDOutDir := 0.0;
    rPIDOutput := 0.0;
END_IF

/Device/Plc Logic/Application/TimeCase:
PROGRAM TimeCase
VAR
	stUTC_Timestamp :SYSTIME ;
	stSYS_Timestamp :ULINT ;
	stGNSS_Timestap :ULINT;
    Result : RTS_IEC_RESULT;
	Uptriger:Standard.R_TRIG;
	Triger AT %IX0.0:BOOL;
	Feed AT %QX0.0:BOOL;	
	TON_F: TON;
	dDelPTime: DINT;
	max_DelPTime:DINT :=0; 
	min_DelPTime: DINT :=-999999;
	iCount: INT;
	dtNow: DATE_AND_TIME;
	dtGNSS: DATE_AND_TIME;
	dtLastGNSS: ULINT;
	iDiffETime: DINT;
	DelPTime: DINT;

END_VAR

//计算时间误差序列
Result := SysTimeRtcHighResGet(stUTC_Timestamp);        
stSYS_Timestamp := TO_ULINT(stUTC_Timestamp);           // ULINT，获取本地时间
dtNow := TO_DT(stUTC_Timestamp / 1000); 		        // 转换为DATE_AND_TIME类型

Uptriger(CLK:=Triger);                                  //检测PPS上升沿
IF Uptriger.Q THEN                                      //上升沿触发后，GPRMC解析，DO0上升沿输出（电平24V）
	Feed:=TRUE;	
	dtGNSS := TO_DT(GVL.stGNSS_Timestap / 1000); 	    // 拿到串口时间数据			                                     
	iDiffETime:=ULINT_TO_DINT(GVL.stGNSS_Timestap-dtLastGNSS);  
	dtLastGNSS:=GVL.stGNSS_Timestap;                    //缓存上一周期时间戳（ms)  
	dDelPTime:=ULINT_TO_DINT(GVL.stGNSS_Timestap - stSYS_Timestamp);       //计算误差	              
	IF iDiffETime = 1000 THEN                           //确保时间更新步进1S
		IF dDelPTime < 0 THEN                           //更新最小值
			IF dDelPTime < min_DelPTime THEN
				min_DelPTime:=dDelPTime;
				DelPTime:=min_DelPTime;                 
			END_IF		
		ELSE                                            //更新最大值
			IF dDelPTime > max_DelPTime THEN
				max_DelPTime:=dDelPTime;
				DelPTime:=max_DelPTime;
			END_IF
		END_IF	
	END_IF				    						
	iCount:=iCount+1;
	IF iCount >= 60 THEN                                //一分钟校一次时间
		GVL.dDelTime:=DelPTime;
		max_DelPTime:=0;
		min_DelPTime:=0;	
		iCount:=0;
	END_IF

END_IF
TON_F(IN:=Feed, PT:=T#100MS, Q=>,ET=>);                 //脉宽200ms（测试时延，为了在示波器看波形）
IF TON_F.Q THEN
	Feed:=FALSE;		
END_IF

/Device/Plc Logic/Application/插值模块/three:
FUNCTION_BLOCK three2
VAR_INPUT
	X:ARRAY [1..5] OF LREAL;
	Y:ARRAY [1..5] OF LREAL;
	y0:REAL:=0;
	yn:REAL:=0;//y0,yn表示的是S''(x0)=f''(x0)=y0，S''(xn)=f''(xn)=yn,自然边界即条件值为0
END_VAR

VAR_OUTPUT
	M :ARRAY [1..5] OF LREAL;
	A: ARRAY [1..5,1..5] OF LREAL;
	D: ARRAY[1..3,1..3] OF LREAL;
	g: ARRAY [1..3] OF LREAL;
	h:ARRAY [1..4] OF LREAL;
END_VAR

VAR
	n:INT:=5;


	ypie:ARRAY [1..5] OF REAL;
	j:INT;
	i:INT;
	u :ARRAY [1..3] OF REAL;
	n_: ARRAY [1..3] OF REAL;
	M_:ARRAY [1..3] OF REAL;
	solve:solvex;


	iCounttest: INT;


	miu :ARRAY [1..4] OF REAL;
END_VAR
//此函数为M值求值函数
//D,h,A,g,M输出量分别为系数矩阵D，插值宽度h，差商表A，g值,M值 
n:=5;
//A(:,1)=Y'
A[1,1]:=Y[1];A[2,1]:=Y[2];A[3,1]:=Y[3];A[4,1]:=Y[4];A[5,1]:=Y[5];

//A(:,1)=Y'
FOR j :=2 TO 5 DO
	FOR i:=j TO 5 DO
		A[i,j]:=(A[i,j-1]- A[i-1,j-1])/(X[i]-X[i-j+1]);
	END_FOR
END_FOR


FOR i:=1 TO (n-1) DO
	h[i]:=X[i+1]-X[i];
END_FOR


//h[1]:=X[2]-X[1];h[2]:=X[3]-X[2];h[3]:=X[4]-X[3];h[4]:=X[5]-X[4];



//D[1,1]:=2;D[2,2]:=2;D[3,3]:=2;

FOR i:=1 TO n-2 DO
	D[i,i]:=2; 
	IF i=1 THEN
		g[i]:=(6/(h[i+1]+h[i]))*(A[i+2,2]-A[i+1,2])-h[i]/(h[i]+h[i+1])*y0;
	ELSIF i=(n-2) THEN
		g[i]:=(6/(h[i+1]+h[i]))*(A[i+2,2]-A[i+1,2])-(1-h[i]/(h[i]+h[i+1]))*yn;
	ELSE
		g[i]:=(6/(h[i+1]+h[i]))*(A[i+2,2]-A[i+1,2]);
	END_IF
END_FOR



FOR i:=2 TO (n-2) DO
	u[i]:=h[i]/(h[i]+h[i+1]);
	n_[i-1]:=h[i]/(h[i-1]+h[i]);
	D[i-1,i]:=n_[i-1];
	D[i,i-1]:=u[i];
END_FOR


solve(M:=D,G:=g,X=>M_);
M[1]:=0;M[5]:=0;M[2]:=M_[1];M[3]:=M_[2];M[4]:=M_[3];

