/Device/Plc Logic/Application/TimeAdd:
PROGRAM TimeAdd
VAR
	icount : INT;
	iSecondLast:INT;
END_VAR

// 监测时统串口状态，时间插值
IF iSecondLast <> GPRMC_1.iSecond THEN
	icount := 0;
ELSE
	icount := icount + 1;
END_IF
iSecondLast := GPRMC_1.iSecond;

IF icount > 2000 THEN
	icount := 0;
END_IF

/Device/Plc Logic/Application/扫描搜索/AGCMa:
rTrg(CLK:=bstart,Q=>);

IF rTrg.Q THEN
	rAGCInit:=rAGCNow;
	rAGCMaxValue:=rAGCNow;
	//rBiasInit:=rCurrentPos-rInterPos;//获取启动时的拉偏量
END_IF

IF bstart THEN
	//搜索换向两次
	IF iCountDirChange=2 THEN
		rSearchNextStepTarget:=rAGCMaxBias;
		IF rStepBias< rSearchNextStepTarget THEN 
			rStepBias:=rStepBias+rStep;
		ELSIF rStepBias> rSearchNextStepTarget THEN
			rStepBias:=rStepBias-rStep;
		ELSE
			rStepBias:=rStepBias;
		END_IF

		IF ABS((rInterPos+rStepBias)-rCurrentPos)<0.002 THEN //若位置达到最强位置，则输出成功 //可能只是路过这里,需要持续
			//需要判断稳定
			iCountBlockEnd:=iCountBlockEnd+1;
		ELSE
			iCountBlockEnd:=0;
		END_IF
		IF iCountBlockEnd>iCountBlockEndMax THEN
			iCountBlockEnd:=iCountBlockEndMax+1;
			//用TON1秒后触发
			ton(IN:=TRUE,PT:=T#1S,Q=>,ET=>);
		END_IF
		IF ton.Q THEN
			bSucess:=TRUE;
		END_IF
	ELSE
		rStepBias:=rStepBias+rDirection*rStep;
		IF rDirection<0 THEN
			//若是向小走
			IF rCurrentPos<rInterPos THEN
				IF rAGCNow<rAGCMaxValue-rSensitivity THEN
					iCountStop1:=iCountStop1+1;
					IF iCountStop1>iCountStopMax THEN
						iCountStop1:=iCountStopMax+1;
						IF bSearchRight THEN
							iCountDirChange:=2;
						ELSE
							iCountDirChange:=iCountDirChange+1;
						END_IF
						rDirection:=rDirection*(-1);
					END_IF
				ELSE
					iCountStop1:=0;	
				END_IF

				//新加的 测试第一阶段搜索正确后不进行第二次搜索
				IF rAGCNow>rAGCInit+rSensitivity THEN
					iCountSearchRight:=iCountSearchRight+1;
				ELSE
					iCountSearchRight:=0;
				END_IF
				IF iCountSearchRight>200 THEN
					iCountSearchRight:=201;
					bSearchRight:=TRUE;
				END_IF

			END_IF
		ELSE
			//若是向正走
			IF rCurrentPos>rInterPos THEN
				IF rAGCNow<rAGCMaxValue-rSensitivity THEN
					iCountStop2:=iCountStop2+1;
					IF iCountStop2>iCountStopMax THEN
						iCountStop2:=iCountStopMax+1;
						IF bSearchRight THEN
							iCountDirChange:=2;
						ELSE
							iCountDirChange:=iCountDirChange+1;
						END_IF
						rDirection:=rDirection*(-1);
					END_IF
				ELSE
					iCountStop2:=0;	
				END_IF

				//新加的
				IF rAGCNow>rAGCInit+rSensitivity THEN
					iCountSearchRight:=iCountSearchRight+1;
				ELSE
					iCountSearchRight:=0;
				END_IF
				IF iCountSearchRight>200 THEN
					iCountSearchRight:=201;
					bSearchRight:=TRUE;
				END_IF

			END_IF
		END_IF
		(*
		IF rAGCNow<rAGCInit-0.05 THEN
			iCountStop1:=iCountStop1+1;
			IF iCountStop1>150 THEN
				iCountDirChange:=iCountDirChange+1;
				rDirection:=rDirection*(-1);
			END_IF
		ELSE
			iCountStop1:=0;	
		END_IF
		*)

		 // 记录最强信号的拉偏量和值
		//IF rAGCNow >= rAGCInit AND rAGCNow> rAGCMaxValue THEN
		IF  rAGCNow> rAGCMaxValue THEN
			rAGCMaxBias := rStepBias;
			rAGCMaxValue := rAGCNow;
		END_IF
	END_IF
ELSE
	rStepBias:=0;
	//清空变量
	iCountDirChange:=0;
	rAGCInit:=0;
	rAGCMaxValue:=0;
	rAGCMaxBias:=0;
	rDirection:=1;
	iCountStop1:=0;
	iCountStop2:=0;
	ton(IN:=FALSE,PT:=T#1S,Q=>,ET=>);
	//rStepBias:=0;
	rSearchNextStepTarget:=0;
	bSucess:=FALSE;
	iCountSearchRight:=0;
	bSearchRight:=FALSE;
	iCountBlockEnd:=0;
END_IF


(*
IF rStepBias< rSearchNextStepTarget THEN 
	rStepBias:=rStepBias+rStep;
ELSIF rStepBias> rSearchNextStepTarget THEN
	rStepBias:=rStepBias-rStep;
ELSE
	rStepBias:=rStepBias;
END_IF*)

/Device/Plc Logic/Application/Ti_ctrl_1:
PROGRAM Ti_ctrl_1
VAR
	Axis3_Ctrl:Ti_Ctrl_FB;
	bRemote2LocalStop:BOOL;
	bLocal2RemoteStop:BOOL;
	Error:INT;

	Axis3Limit_pos:REAL;//正软限位
	Axis3Limit_Neg:REAL;//负软限位

	bRTriger:Standard.R_TRIG;//本控上升沿
	bFTriger:Standard.F_TRIG;//远控下降沿
	Stop3_Count: INT;
	bStop_3: BOOL;

	//指向模式自跟踪
	rPosModeStepBias:LREAL;//指向模式自跟踪拉偏累计值
	rPosModeStep:LREAL:=0.005;//指向模式自跟踪步长，积分用
	rStepBiasMax:LREAL:=2;//指向模式拉偏最大值

	//程引拉偏
	rStepBias:LREAL;//步进拉偏累计值
// 	rStep:LREAL:=0.0002;//步长，与控制周期有关，1ms周期对应1秒内累积0.0002*1000=0.2°
// 	rStep:LREAL:=0.01;//步长，与控制周期有关，50ms周期对应1秒内累积0.01*20=0.2°
	rStep:LREAL:=0.004;//步长，与控制周期有关，20ms周期对应1秒内累积0.004*50=0.2°

	//自跟踪拉偏
	rAuToStepBias:LREAL;//步进拉偏累计值
// 	rAutoStep:LREAL:=0.005;//步长
	rAutoStep:LREAL:=0.01;//步长
	TbAutoTrigger:Standard.F_TRIG;//自跟踪关闭的下降沿
	RbAutoTrigger:Standard.R_TRIG;//自跟踪开启的上升沿

	rAutoTrackingBiasMax:LREAL:=300;//自跟踪拉偏最大值
	rLocalInitPosModeSpeed: REAL;
	rRemoteInitPosModeSpeed: REAL;
	iCountOffAuto: INT;

	iCasePBAutoTrack:INT:=2;//程序引导自跟踪切换 
// 	rKAuToStepBias:LREAL:=0.25;
	rKAuToStepBias:LREAL:=0.16;
	bVisError:BOOL; //报错可视化标识
END_VAR
IF GVL.Error_code <> 0 THEN
	bVisError := TRUE;
ELSE
	bVisError := FALSE;
END_IF
(*
//远控轴参量赋值
Axis2Remote.iMode:=Modbus_Slave.iMode_2;
Axis2Remote.rVelCmd:=Modbus_Slave.rVelcmd_2;
Axis2Remote.rPosCmd:=Modbus_Slave.rPosCmd_2;
Axis2Remote.rP:=Modbus_Slave.rP_2;
Axis2Remote.rI:=Modbus_Slave.rI_2;
Axis2Remote.rD:=Modbus_Slave.rD_2;
Axis2Remote.rPIDThre:=Modbus_Slave.rThreshold_2;
Axis2Remote.rAcceleration:=Modbus_Slave.rAcceleration_2;
Axis2Remote.rDeceleration:=Modbus_Slave.rDeceleration_2;
Axis2Remote.rVel_Limit:=Modbus_Slave.rVelLim_2;
*)
// 倾斜轴状态写入
Axis3Status.Error := GVL.bTiStsBit3;
Axis3Status.ErrorID := GVL.eTiErrorcode;
Axis3Status.bServo_Enable := GVL.bTiStsBit0 AND GVL.bTiStsBit1 AND GVL.bTiStsBit2;
Axis3Status.bBrake := NOT (GVL.bTiStsBit0 AND GVL.bTiStsBit1 AND GVL.bTiStsBit2);
Axis3Status.Disabled := NOT (GVL.bTiStsBit0 AND GVL.bTiStsBit1 AND GVL.bTiStsBit2);
Axis3Remote.rSoft_limit_Negative:=-190;Axis3Remote.rSoft_limit_Postive:=190;
Axis3Local.rSoft_limit_Negative:=-190;Axis3Local.rSoft_limit_Postive:=190;

//速度的写入
rFctVelReal_3:=DINT_TO_REAL(diTiActVel)/524288.0*360.0;
//位置的写入，方位0对应编码器0，所以实际方位是：-1*编码器值
//rFctPosReal_3:=DINT_TO_REAL(diTiActPos)/524288.0*360.0-11.413-0.08;
rFctPosReal_3:=DINT_TO_REAL(diTiActPos)/524288.0*360.0;
//软限位控制
Axis3Limit_pos:=190;
Axis3Limit_Neg:=-190;
IF Axis3Remote.rPosCmd>Axis3Limit_pos THEN
	Axis3Remote.rPosCmd:=190;
ELSIF Axis3Remote.rPosCmd<Axis3Limit_Neg THEN
	 Axis3Remote.rPosCmd:=-190;  
END_IF

IF Axis3Local.rPosCmd>Axis3Limit_pos THEN
	Axis2Local.rPosCmd:=190;
ELSIF Axis3Local.rPosCmd<Axis3Limit_Neg THEN
	 Axis3Local.rPosCmd:=-190;  
END_IF

//停止标志符号判断
IF  ABS(rFctVelReal_3)<0.035 THEN
	Stop3_Count:=Stop3_Count+1;
	IF Stop3_Count>100 THEN
		Stop3_Count:=101;
		bStop_3:=TRUE;;
	END_IF
ELSE
	Stop3_Count:=0;
	bStop_3:=FALSE;
END_IF
Axis3Status.Moving := NOT bStop_3;
//PID使能赋值
IF Axis3Remote.iMode=2 OR Axis3Remote.iMode=4 THEN
	Axis3Remote.bPIDEnable:=TRUE;
ELSE
	Axis3Remote.bPIDEnable:=FALSE;
END_IF

//本远控逻辑保护
//远控切本控逻辑保护
bRTriger(CLK:=GVL.bLocalCtrl);
bFTriger(CLK:=GVL.bLocalCtrl);

IF Axis3Status.bServo_Enable AND (bRTriger.Q ) THEN//如果速度不为0且本控发生切换，则减速停止标识为True
	bRemote2LocalStop:=TRUE;
END_IF
IF bRemote2LocalStop  THEN //若减速停止标识符为True 

	IF  bStop_3=TRUE THEN//且电机速度不为0 开始减速 减速完成后下使能，下使能完成后复位标识符复位
		Axis3Local.iMode:=0;
		Axis3Remote.iMode:=0;
		IF Axis3Status.bServo_Enable=FALSE THEN
			bRemote2LocalStop:=FALSE;
		END_IF
	ELSE
		Axis3Remote.iMode:=7;
	END_IF
END_IF

