/Device/Plc Logic/Application/PID:
FUNCTION_BLOCK PID
VAR_INPUT
    rTarget : REAL;       (* 设定值 *)
    rFeedback : REAL;       (* 反馈值 *)
	rPosLimPositive:LREAL;//位置正限位
	rPosLimNegative:LREAL;//位置反限位
	rKp:REAL;     //比例增益
	rKi:REAL;     //积分增益
	rKd:REAL;     //微分增益
	iThreshold:INT;//积分项开启的位置阈值
	bPIDEnable:BOOL:=TRUE;//PID使能
	rVelLim:LREAL;//速度限制
END_VAR
VAR_OUTPUT
    rPIDOutput : LREAL:=0;         //带方向的输出速度
	rPIDtrace : LREAL:=0;         //带方向的输出速度
END_VAR
VAR
	//rPIDOutPut: REAL:=0.0;
	rLastError: LREAL:=0.0;(*上一次误差*)
	rErrorNow:LREAL:=0.0;(*当前误差*)
    rIntegralNew : LREAL := 0.0; (* 积分项 *)
    rDerivativeNew : LREAL := 0.0; (* 微分项 *)
	rDelta: LREAL;(*增量*)
	rProportionNew: LREAL;

	//iAzPIDEnable: INT;
END_VAR



IF (bPIDEnable>0) THEN //如果PID使能
	IF rTarget=rFeedback THEN
		rPIDOutput:=0;	
	ELSE

		rErrorNow:=rTarget-rFeedback;//计算当前误差 en
		rProportionNew:=rErrorNow;//比例项
		//积分项
		IF rFeedback>rPosLimNegative AND rFeedback<rPosLimPositive THEN //若在软限位之内，工作时开启积分项
			IF (ABS(rTarget-rFeedback)<iThreshold) THEN//位置差小于积分阈值
				rIntegralNew:= rIntegralNew+rErrorNow; //积分项
			ELSE
				rIntegralNew:=0;
			END_IF;
		ELSE //不在软限位范围内,则积分项为0
			rIntegralNew:=0;
		END_IF

		//PID输出
		rPIDOutPut:=rKp*rProportionNew+rKi*rIntegralNew;
		rPIDtrace:=rKp*rProportionNew+rKi*rIntegralNew;


		//PID限速

			IF rPIDOutput<(-rVelLim) THEN
				rPIDOutput:=-rVelLim;
			ELSIF rPIDOutput>rVelLim THEN
				rPIDOutput:=rVelLim;
			END_IF


		IF rFeedback>rPosLimPositive AND rPIDOutput>0 THEN 
			rPIDOutput:=0;
		END_IF
		IF rFeedback<rPosLimNegative AND rPIDOutput<0 THEN
			rPIDOutput:=0;
		END_IF

		rLastError:=rErrorNow;//将当前误差赋值给上一次误差

	END_IF
ELSE//非使能清零PID各项
	rProportionNew:=0.0;
	rIntegralNew:=0.0;
	rPIDOutput:=0.0;
END_IF

